def bar(index, open_, high, low, close):
    moment = datetime(2026, 7, 7, 0, 0) + timedelta(minutes=index)
    return Bar(
        time=moment,
        time_text=moment.strftime("%Y.%m.%d %H:%M"),
        open=open_,
        high=high,
        low=low,
        close=close,
        tick_volume=1,
    )


def mql_input_defaults(path: str | Path) -> dict[str, str]:
    defaults: dict[str, str] = {}
    for raw_line in Path(path).read_text(encoding="utf-8").splitlines():
        line = raw_line.strip()
        if not line.startswith("input ") or "=" not in line:
            continue
        name_part, value_part = line.split("=", 1)
        parts = name_part.split()
        if not parts:
            continue
        name = parts[-1]
        defaults[name] = value_part.rstrip(";").strip()
    return defaults


def tester_set_values(path: str | Path) -> dict[str, str]:
    values: dict[str, str] = {}
    for raw_line in Path(path).read_text(encoding="utf-8").splitlines():
        line = raw_line.strip()
        if not line or line.startswith(";") or "=" not in line:
            continue
        name, value = line.split("=", 1)
        values[name.strip()] = value.split("||", 1)[0].strip()
    return values


def manual_strategy_tester_heartbeat_fields(
    *,
    available: bool = False,
    recommended: bool = False,
    collect_only: str = "",
    start_after: str = "",
    steps: list[dict[str, object]] | None = None,
) -> dict[str, object]:
    manual_steps = steps or []
    return {
        "manual_strategy_tester_available": available,
        "manual_strategy_tester_recommended": recommended,
        "manual_strategy_tester_status": "available" if available else "missing_plan",
        "manual_strategy_tester_reasons": [],
        "manual_strategy_tester_auto_launch_ready": False,
        "manual_strategy_tester_auto_launch_status": "blocked" if recommended else "",
        "manual_strategy_tester_auto_launch_blockers": ["terminal_running"] if recommended else [],
        "manual_strategy_tester_auto_launch_blocked_by_running_terminal": recommended,
        "manual_strategy_tester_terminal_running": recommended,
        "manual_strategy_tester_collect_only_command_text": collect_only,
        "manual_strategy_tester_collect_only_note": "",
        "manual_strategy_tester_manual_run_start_after": start_after,
        "manual_strategy_tester_step_count": len(manual_steps),
        "manual_strategy_tester_steps": manual_steps,
        "manual_strategy_tester_note": "",
    }


