def manual_test_queue_with_optimization_heartbeat_fields(
    *,
    entries: list[dict[str, object]] | None = None,
    step_count: int | None = None,
    waiting_count: int | None = None,
    ready_to_collect_count: int = 0,
    step_report_ready_count: int | None = None,
    step_waiting_report_count: int | None = None,
    step_launch_needed_count: int | None = None,
    execution_checklist: list[dict[str, object]] | None = None,
    strategy_tester_targets: list[dict[str, object]] | None = None,
    operation_cards: list[dict[str, object]] | None = None,
    static_strategy_configs: list[str] | None = None,
    static_candidate_labels: list[str] | None = None,
) -> dict[str, object]:
    def replace_queue_path(value: object) -> object:
        if isinstance(value, str):
            return value.replace(
                "runtime/latest_mt5_manual_test_queue.json",
                "runtime/latest_mt5_manual_test_queue_with_optimization.json",
            )
        if isinstance(value, list):
            return [replace_queue_path(item) for item in value]
        if isinstance(value, dict):
            return {key: replace_queue_path(item) for key, item in value.items()}
        return value

    base = manual_test_queue_heartbeat_fields(
        entries=entries,
        step_count=step_count,
        waiting_count=waiting_count,
        ready_to_collect_count=ready_to_collect_count,
        step_report_ready_count=step_report_ready_count,
        step_waiting_report_count=step_waiting_report_count,
        step_launch_needed_count=step_launch_needed_count,
        execution_checklist=execution_checklist,
        strategy_tester_targets=strategy_tester_targets,
        operation_cards=operation_cards,
    )
    mapped = {
        key.replace("manual_test_queue", "manual_test_queue_with_optimization", 1): replace_queue_path(value)
        for key, value in base.items()
    }
    configs = static_strategy_configs or [
        "methods/swing_eval/mt5/TesterConfigs/Swing_Evaluation_Trader_optimization.ini"
    ]
    labels = static_candidate_labels or ["sell_hour12_m30m15_2025"]
    mapped.update(
        {
            "manual_test_queue_with_optimization_path": (
                "runtime/latest_mt5_manual_test_queue_with_optimization.json"
            ),
            "manual_test_queue_with_optimization_static_strategy_config_count": len(configs),
            "manual_test_queue_with_optimization_static_strategy_configs": configs,
            "manual_test_queue_with_optimization_static_candidate_label_count": len(labels),
            "manual_test_queue_with_optimization_static_candidate_labels": labels,
        }
    )
    return mapped


