    def test_spec_coverage_tracks_buy_next_action_runner_runtime_artifact(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            for artifact_name, relative_path in RUNTIME_ARTIFACTS:
                if artifact_name == "mt5_next_action_run_buy":
                    continue
                path = root / relative_path
                path.parent.mkdir(parents=True, exist_ok=True)
                path.write_text(
                    json.dumps({"ok": True, "generated_at": "2026.07.13 21:00"}) + "\n",
                    encoding="utf-8",
                )

            artifacts = runtime_coverage(root, now_epoch=time.time(), max_artifact_age_seconds=3600)
            reasons = completion_reasons(components=[], artifacts=artifacts, mql5_artifacts=[])

        buy_runner = next(row for row in artifacts if row["name"] == "mt5_next_action_run_buy")
        self.assertEqual(buy_runner["path"], "runtime/latest_mt5_next_action_run_buy.json")
        self.assertFalse(buy_runner["exists"])
        self.assertIn(
            "missing_runtime_artifacts:runtime/latest_mt5_next_action_run_buy.json",
            reasons,
        )

