    def test_spec_coverage_flags_stale_history_data_time_even_when_file_is_fresh(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            history_status_path = root / "runtime" / "latest_history_status.json"
            history_status_path.parent.mkdir(parents=True, exist_ok=True)
            history_status_path.write_text(
                json.dumps(
                    {
                        "ok": True,
                        "generated_at": "2026.07.17 05:00",
                        "server_time": "2026.07.16 00:00:00",
                        "timeframes": {
                            "M1": {
                                "bars": 10080,
                                "expected_bars": 10080,
                                "complete": True,
                                "last_time": "2026.07.16 00:00",
                            }
                        },
                    }
                )
                + "\n",
                encoding="utf-8",
            )
            now_epoch = datetime.strptime("2026.07.17 05:00:00", "%Y.%m.%d %H:%M:%S").timestamp()
            artifact = artifact_summary(
                root,
                "history_status",
                "runtime/latest_history_status.json",
                now_epoch=now_epoch,
                max_age_seconds=3600,
                max_history_data_age_seconds=12 * 60 * 60,
            )
            reasons = completion_reasons(components=[], artifacts=[artifact], mql5_artifacts=[])
            actions = build_spec_next_actions(
                workspace=root,
                artifacts=[artifact],
                reasons=reasons,
                history_request={"state": "idle", "pending": False},
            )
            markdown = format_spec_coverage_markdown(
                {
                    "max_history_data_age_seconds": 12 * 60 * 60,
                    "runtime_artifacts": [artifact],
                    "history_request": {"state": "idle"},
                    "next_actions": actions,
                    "components": [],
                    "mql5_artifacts": [],
                    "phases": [],
                }
            )

        self.assertTrue(artifact["fresh"])
        self.assertFalse(artifact["history_data_fresh"])
        self.assertEqual(artifact["history_server_time"], "2026.07.16 00:00:00")
        self.assertGreater(artifact["history_server_time_age_seconds"], 12 * 60 * 60)
        stale_reason = next(reason for reason in reasons if reason.startswith("history_data_stale:history_status:"))
        self.assertIn("server_time_age_seconds", stale_reason)
        history_action = next(action for action in actions if action["id"] == "refresh_history")
        self.assertIn(stale_reason, history_action["reasons"])
        self.assertTrue(any("complete bars" in step for step in history_action["manual_steps"]))
        self.assertIn("History data freshness: fresh=False", markdown)
        self.assertIn("history_data_fresh=False", markdown)

    def test_spec_coverage_next_action_refreshes_winrate_and_risk_shape_artifacts(self):
        artifacts = [
            {
                "name": "history",
                "exists": True,
                "fresh": False,
                "path": "runtime/latest_history_168h.json",
                "age_seconds": 100000,
            },
            {
                "name": "winrate_fit",
                "exists": True,
                "fresh": False,
                "path": "runtime/latest_winrate_fit.json",
                "age_seconds": 100000,
                "winrate_adopted": True,
                "winrate_rules": "score >= 55",
            },
            {
                "name": "risk_shape_weight_search",
                "exists": False,
                "fresh": False,
                "path": "runtime/latest_risk_shape_weight_search.json",
            },
        ]
        actions = build_spec_next_actions(
            workspace=Path("/tmp"),
            artifacts=artifacts,
            reasons=[
                "stale_runtime_artifacts:history,winrate_fit",
                "missing_runtime_artifacts:runtime/latest_risk_shape_weight_search.json",
            ],
        )

        history_action = next(item for item in actions if item["id"] == "refresh_history")
        self.assertIn("stale_runtime_artifacts:history", history_action["reasons"])
        self.assertFalse(any("winrate_fit" in reason for reason in history_action["reasons"]))
        self.assertFalse(any("risk_shape_weight_search" in reason for reason in history_action["reasons"]))

        action = next(item for item in actions if item["id"] == "refresh_fit_quality_artifacts")
        commands = {command["label"]: command["command"] for command in action["commands"]}

        self.assertEqual(action["priority"], 22)
        self.assertEqual(action["area"], "fit_artifacts")
        self.assertIn("methods/swing_eval/analysis/winrate_fit.py", commands["refresh_winrate_fit"])
        self.assertIn("--output-json runtime/latest_winrate_fit.json", commands["refresh_winrate_fit"])
        self.assertIn("methods/swing_eval/analysis/backtest.py", commands["refresh_risk_shape_backtest"])
        self.assertIn("reports/risk_shape_backtest_168h_min40.xlsx", commands["refresh_risk_shape_backtest"])
        self.assertIn("methods/swing_eval/analysis/weight_search.py", commands["refresh_risk_shape_weight_search"])
        self.assertIn("--output-json runtime/latest_risk_shape_weight_search.json", commands["refresh_risk_shape_weight_search"])
        self.assertIn("--walk-forward", commands["refresh_risk_shape_weight_search"])
        self.assertIn("methods/swing_eval/analysis/promotion_gate.py", commands["refresh_promotion_gate_after_fit_artifacts"])
        self.assertIn("stale_runtime_artifacts:winrate_fit", action["reasons"])
        self.assertIn(
            "missing_runtime_artifacts:runtime/latest_risk_shape_weight_search.json",
            action["reasons"],
        )
        self.assertFalse(any("history" in reason for reason in action["reasons"]))
        self.assertIn("winrate_fit is stale", action["manual_steps"][0])
        self.assertTrue(any("History artifact is stale" in step for step in action["manual_steps"]))

    def test_spec_coverage_reports_mql5_marker_gaps(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            (root / "methods" / "swing_eval" / "docs").mkdir(parents=True)
            (root / "methods" / "swing_eval" / "tests").mkdir(parents=True, exist_ok=True)
            (root / "runtime").mkdir()
            (root / "methods" / "swing_eval" / "docs" / "swing-evaluation-trading-system-spec.md").write_text("# Spec\n", encoding="utf-8")
            for name, relative_path, _ in MQL5_ARTIFACTS:
                path = root / relative_path
                path.parent.mkdir(parents=True, exist_ok=True)
                markers = list(mql5_artifact_required_markers(name, relative_path))
                if name == "predictor_indicator":
                    markers = [marker for marker in markers if marker != "DRY-RUN ENTRY"]
                path.write_text("\n".join(markers) + "\n", encoding="utf-8")
            (root / "methods" / "swing_eval" / "tests" / "test_mql5_artifacts.py").write_text(
                "\n".join(relative_path for _, relative_path, _ in MQL5_ARTIFACTS) + "\n",
                encoding="utf-8",
            )
            for artifact_name, relative_path in RUNTIME_ARTIFACTS:
                path = root / relative_path
                path.parent.mkdir(parents=True, exist_ok=True)
                payload: dict[str, object] = {"ok": True, "generated_at": "2026.07.13 21:00"}
                if artifact_name == "bridge_status":
                    payload["operational_status"] = "ready"
                elif artifact_name == "promotion_gate":
                    payload["decision"] = "ready"
                elif artifact_name == "mt5_tester_status":
                    payload["operational_status"] = "ready"
                    payload["status_watch_heartbeat"] = {"compatible": True}
                elif artifact_name == "mt5_back_forward_run":
                    payload["evidence_state"] = "executed_ok"
                elif artifact_name.startswith("score_weight_search_"):
                    payload["walk_forward"] = {"aggregate": {"status": "walk_forward_candidate_passed"}}
                elif artifact_name.startswith("score_weight_set_"):
                    payload["written"] = True
                    payload["walk_forward_status"] = "walk_forward_candidate_passed"
                path.write_text(json.dumps(payload) + "\n", encoding="utf-8")

            payload = build_spec_coverage(workspace_root=root, max_artifact_age_seconds=3600)

        self.assertFalse(payload["goal_completion_proven"])
        self.assertEqual(payload["mql5_artifact_marker_gap_count"], 1)
        self.assertIn(
            "mql5_artifact_markers_missing:predictor_indicator=DRY-RUN ENTRY",
            payload["not_complete_reasons"],
        )
        predictor_row = next(row for row in payload["mql5_artifacts"] if row["name"] == "predictor_indicator")
        self.assertFalse(predictor_row["markers_ok"])
        self.assertEqual(predictor_row["missing_markers"], ["DRY-RUN ENTRY"])
        action = next(item for item in payload["next_actions"] if item["id"] == "fix_mql5_artifact_coverage")
        self.assertEqual(action["priority"], 8)
        self.assertIn(
            "mql5_artifact_markers_missing:predictor_indicator=DRY-RUN ENTRY",
            action["reasons"],
        )
        commands = {command["label"]: command["command"] for command in action["commands"]}
        self.assertIn("methods/swing_eval/analysis/mt5_compile_status.py", commands["refresh_compile_status"])
        self.assertIn("methods/swing_eval/analysis/spec_coverage.py", commands["rerun_spec_coverage"])
        self.assertIn("Fix MQL5 artifact marker gaps", action["manual_steps"][0])
        markdown = format_spec_coverage_markdown(payload)
        self.assertIn("fix_mql5_artifact_coverage", markdown)
        self.assertIn("missing: DRY-RUN ENTRY", markdown)

