    def test_spec_coverage_strategy_back_forward_decision_blocks_degraded_forward(self):
        artifacts = [
            {
                "name": "bridge_status",
                "exists": True,
                "operational_status": "ready",
                "bridge_log_activity_status": "ea_post_recent",
            },
            {
                "name": "bridge_status_watch",
                "exists": True,
                "bridge_log_activity_status": "ea_post_recent",
            },
            {"name": "promotion_gate", "decision": "ready"},
            {
                "name": "mt5_tester_status",
                "operational_status": "ready",
                "status_watch_compatible": True,
            },
            {
                "name": "mt5_back_forward_run",
                "evidence_state": "executed_degraded",
                "manual_prerequisites_ready": True,
            },
            {
                "name": "mt5_strategy_tester_analysis",
                "strategy_tester_analysis_back_forward_evidence_state": "executed_degraded",
                "strategy_tester_analysis_back_forward_performance_status": (
                    "forward_degraded_vs_backtest"
                ),
                "strategy_tester_analysis_back_forward_decision_status": "forward_regression",
                "strategy_tester_analysis_back_forward_decision_adoptable": False,
                "strategy_tester_analysis_back_forward_decision_next_action": (
                    "reject_or_refit_before_promotion"
                ),
                "strategy_tester_analysis_back_forward_decision_reason": (
                    "Forward result degraded versus the backtest beyond the allowed threshold."
                ),
                "strategy_tester_analysis_back_forward_decision_thresholds": {
                    "min_closed": 30,
                    "break_even_pf": 1.0,
                    "break_even_avg_r": 0.0,
                    "degraded_pf_delta": -0.2,
                    "degraded_avg_r_delta": -0.05,
                },
                "strategy_tester_analysis_back_forward_decision_backtest_trades": 44,
                "strategy_tester_analysis_back_forward_decision_forward_trades": 37,
                "strategy_tester_analysis_back_forward_decision_forward_pf": 0.82,
                "strategy_tester_analysis_back_forward_decision_forward_avg_r": -0.04,
                "strategy_tester_analysis_back_forward_decision_forward_pf_delta_vs_backtest": -0.35,
                "strategy_tester_analysis_back_forward_decision_forward_avg_r_delta_vs_backtest": -0.08,
            },
            {
                "name": "score_weight_search_buy_rr4",
                "walk_forward_aggregate_status": "walk_forward_candidate_passed",
            },
            {
                "name": "score_weight_set_buy_rr4",
                "exists": True,
                "ok": True,
                "written": True,
                "walk_forward_status": "walk_forward_candidate_passed",
            },
            {
                "name": "score_weight_search_sell_rr4",
                "walk_forward_aggregate_status": "walk_forward_candidate_passed",
            },
            {
                "name": "score_weight_set_sell_rr4",
                "exists": True,
                "ok": True,
                "written": True,
                "walk_forward_status": "walk_forward_candidate_passed",
            },
        ]
        for artifact in artifacts:
            artifact.setdefault("exists", True)
            artifact.setdefault("path", f"runtime/{artifact['name']}.json")

        reasons = completion_reasons(components=[], artifacts=artifacts, mql5_artifacts=[])
        self.assertIn("mt5_back_forward_executed_not_adoptable:executed_degraded", reasons)
        self.assertNotIn("mt5_back_forward_not_executed:executed_degraded", reasons)
        self.assertIn("mt5_back_forward_decision:forward_regression", reasons)

        actions = build_spec_next_actions(workspace=Path("/tmp"), artifacts=artifacts, reasons=reasons)
        run_action = next(item for item in actions if item["id"] == "run_or_collect_mt5_back_forward")
        commands = {command["label"]: command["command"] for command in run_action["commands"]}
        self.assertIn("refresh_strategy_tester_analysis", commands)
        self.assertNotIn("execute_with_mt5_launch", commands)
        self.assertIn(
            "Do not promote this Strategy Tester candidate as-is; "
            "refit or adjust the candidate before running another promotion gate.",
            run_action["manual_steps"],
        )
        self.assertIn(
            "Strategy analysis Back/Forward metrics: backtest_trades=44, forward_trades=37, "
            "forward_pf=0.82, forward_avg_r=-0.04, forward_pf_delta=-0.35, "
            "forward_avg_r_delta=-0.08",
            run_action["manual_steps"],
        )

