    def test_spec_coverage_prefers_manual_queue_collect_filters_for_mt5_runner_artifacts(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            runtime = root / "runtime"
            runtime.mkdir()
            old_back = (
                "python3 methods/swing_eval/analysis/mt5_back_forward_run.py --mode both --collect-only "
                "--csv-modified-after '2026.07.17 15:04'"
            )
            new_back = (
                "python3 methods/swing_eval/analysis/mt5_back_forward_run.py --mode both --collect-only "
                "--csv-modified-after '2026.07.17 16:05'"
            )
            old_sell = (
                "python3 methods/swing_eval/analysis/mt5_tester_run.py --focus-side sell --collect-only "
                "--csv-modified-after '2026.07.17 15:05'"
            )
            new_sell = (
                "python3 methods/swing_eval/analysis/mt5_tester_run.py --focus-side sell --collect-only "
                "--csv-modified-after '2026.07.17 16:05'"
            )
            old_buy = (
                "python3 methods/swing_eval/analysis/mt5_tester_run.py --focus-side buy --collect-only "
                "--csv-modified-after '2026.07.17 15:05'"
            )
            new_buy = (
                "python3 methods/swing_eval/analysis/mt5_tester_run.py --focus-side buy --collect-only "
                "--csv-modified-after '2026.07.17 16:05'"
            )
            (runtime / "latest_mt5_back_forward_run.json").write_text(
                json.dumps(
                    {
                        "generated_at": "2026.07.17 15:04",
                        "evidence_state": "plan_only",
                        "execution_hints": {
                            "execute_command_text": (
                                "python3 methods/swing_eval/analysis/mt5_back_forward_run.py --mode both --execute"
                            ),
                            "collect_only_command_text": old_back,
                        },
                        "manual_strategy_tester": {
                            "available": True,
                            "recommended_collect_only_command_text": old_back,
                            "manual_run_start_after": "2026.07.17 15:04",
                        },
                        "manual_collect_readiness": {
                            "ready": True,
                            "status": "ready_to_collect",
                            "modified_after": "2026.07.17 15:04",
                        },
                        "mt5_strategy_tester_pack": {
                            "available": True,
                            "status": "waiting_for_reports",
                            "collect_command_text": old_back,
                            "manual_run_start_after": "2026.07.17 15:04",
                        },
                    }
                )
                + "\n",
                encoding="utf-8",
            )
            for path, side, old_command in (
                ("latest_mt5_next_action_run.json", "sell", old_sell),
                ("latest_mt5_next_action_run_buy.json", "buy", old_buy),
            ):
                (runtime / path).write_text(
                    json.dumps(
                        {
                            "generated_at": "2026.07.17 15:05",
                            "target": "score_weight_sample_collection",
                            "focus_side": side,
                            "execution_hints": {
                                "execute_command_text": (
                                    "python3 methods/swing_eval/analysis/mt5_tester_run.py "
                                    f"--focus-side {side}"
                                ),
                                "collect_only_command_text": old_command,
                            },
                            "manual_strategy_tester": {
                                "available": True,
                                "recommended_collect_only_command_text": old_command,
                                "manual_run_start_after": "2026.07.17 15:05",
                            },
                            "manual_collect_readiness": {
                                "ready": True,
                                "status": "ready_to_collect",
                                "modified_after": "2026.07.17 15:05",
                            },
                        }
                    )
                    + "\n",
                    encoding="utf-8",
                )
            (runtime / "latest_mt5_manual_test_queue.json").write_text(
                json.dumps(
                    {
                        "generated_at": "2026.07.17 16:05",
                        "status": "ready_to_collect_all",
                        "entries": [
                            {
                                "available": True,
                                "id": "back_forward",
                                "source_json": "runtime/latest_mt5_back_forward_run.json",
                                "manual_run_start_after": "2026.07.17 16:05",
                                "collect_modified_after": "2026.07.17 16:05",
                                "collect_only_command_text": new_back,
                            },
                            {
                                "available": True,
                                "id": "score_weight_sell",
                                "source_json": "runtime/latest_mt5_next_action_run.json",
                                "manual_run_start_after": "2026.07.17 16:05",
                                "collect_modified_after": "2026.07.17 16:05",
                                "collect_only_command_text": new_sell,
                            },
                            {
                                "available": True,
                                "id": "score_weight_buy",
                                "source_json": "runtime/latest_mt5_next_action_run_buy.json",
                                "manual_run_start_after": "2026.07.17 16:05",
                                "collect_modified_after": "2026.07.17 16:05",
                                "collect_only_command_text": new_buy,
                            },
                        ],
                    }
                )
                + "\n",
                encoding="utf-8",
            )

            artifacts = runtime_coverage(
                root,
                now_epoch=time.time(),
                max_artifact_age_seconds=3600,
            )
            by_name = {row["name"]: row for row in artifacts}
            back_forward = by_name["mt5_back_forward_run"]
            sell_runner = by_name["mt5_next_action_run"]
            buy_runner = by_name["mt5_next_action_run_buy"]

            self.assertEqual(back_forward["manual_collect_only_command_text"], new_back)
            self.assertEqual(
                back_forward["mt5_strategy_tester_pack_collect_command_text"],
                new_back,
            )
            self.assertEqual(back_forward["execution_hints"]["collect_only_command_text"], new_back)
            self.assertEqual(back_forward["manual_collect_modified_after"], "2026.07.17 16:05")
            self.assertEqual(sell_runner["manual_collect_only_command_text"], new_sell)
            self.assertEqual(sell_runner["execution_hints"]["collect_only_command_text"], new_sell)
            self.assertEqual(buy_runner["manual_collect_only_command_text"], new_buy)
            self.assertEqual(buy_runner["execution_hints"]["collect_only_command_text"], new_buy)

            actions = build_spec_next_actions(
                workspace=root,
                artifacts=artifacts,
                reasons=[
                    "mt5_back_forward_not_executed:plan_only",
                    "score_weight_search_sell_rr4_walk_forward_not_passed",
                    "score_weight_search_buy_rr4_walk_forward_not_passed",
                ],
            )
            action_commands = {
                action["id"]: {
                    command["label"]: command["command"]
                    for command in action.get("commands", [])
                }
                for action in actions
            }
            self.assertEqual(
                action_commands["run_or_collect_mt5_back_forward"]["collect_manual_results"],
                new_back,
            )
            self.assertEqual(
                action_commands["score_weight_follow_up_sell"]["collect_manual_sample_collection"],
                new_sell,
            )
            self.assertEqual(
                action_commands["score_weight_follow_up_buy"]["collect_manual_side_sample_collection"],
                new_buy,
            )
            action_text = json.dumps(actions, ensure_ascii=False)
            self.assertNotIn(old_back, action_text)
            self.assertNotIn(old_sell, action_text)
            self.assertNotIn(old_buy, action_text)

