    def test_strategy_back_forward_decision_includes_sample_shortage_recovery(self):
        decision = back_forward_decision_summary(
            {
                "exists": True,
                "mode": "both",
                "run_id_prefix": "run_20260713_1404_mt5_strategy",
                "evidence_state": "executed_sample_shortage",
                "performance_status": "forward_sample_shortage",
                "performance_available": True,
                "performance_thresholds": {"min_closed": 30},
                "performance_rows": [
                    {
                        "dataset": "backtest",
                        "trades": 100,
                        "meets_min_closed": True,
                        "pf": 1.32,
                        "avg_r": 0.12,
                    },
                    {
                        "dataset": "forward",
                        "trades": 3,
                        "meets_min_closed": False,
                        "pf": 3.4,
                        "avg_r": 0.8,
                    },
                ],
                "execution_conditions": {
                    "per_step_timeout_seconds": 3600,
                    "since_minutes": 240.0,
                    "min_closed": 30,
                    "from_date": "2026.06.30",
                    "to_date": "2026.07.08",
                    "forward_mode": "3",
                    "sync_expert_parameters_set": True,
                    "skip_archive_preview": True,
                    "max_ready_status_age_seconds": 600,
                },
            }
        )

        self.assertEqual(decision["status"], "sample_shortage")
        self.assertFalse(decision["adoptable"])
        self.assertEqual(
            decision["next_action"],
            "extend_back_forward_window_or_collect_more_closed_trades",
        )
        recovery = decision["sample_shortage_recovery"]
        self.assertEqual(recovery["range_strategy"], "extend_to_default_full_year")
        self.assertEqual(recovery["current_from_date"], "2026.06.30")
        self.assertEqual(recovery["current_to_date"], "2026.07.08")
        self.assertEqual(recovery["current_range_days"], 8)
        self.assertEqual(recovery["suggested_from_date"], "2025.01.01")
        self.assertEqual(recovery["suggested_to_date"], "2025.12.31")
        self.assertIn("--from-date 2025.01.01", recovery["command_text"])
        self.assertIn("--to-date 2025.12.31", recovery["command_text"])
        self.assertIn(
            "--run-id-prefix run_20260713_1404_mt5_strategy_extended_window",
            recovery["command_text"],
        )
        self.assertIn("--sync-expert-parameters-set", recovery["command_text"])
        self.assertIn("--skip-archive-preview", recovery["command_text"])
        self.assertIn(
            "--max-ready-status-age-seconds 600",
            decision["sample_shortage_recovery_command_text"],
        )

