    def test_spec_artifact_summary_extracts_blocking_prior_actions(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            status_path = root / "runtime" / "latest_mt5_tester_status.json"
            status_path.parent.mkdir(parents=True, exist_ok=True)
            status_path.write_text(
                json.dumps(
                    {
                        "next_action_runner": {
                            "blocking_prior_action_count": 1,
                            "blocking_prior_actions": [
                                {
                                    "priority": 1,
                                    "area": "bridge",
                                    "action": "restore_bridge",
                                    "reason": "EA posting is stale.",
                                    "execution_kind": "bridge_status_refresh",
                                    "command_text": "python3 methods/swing_eval/analysis/bridge_status.py",
                                    "runner_execute_hint": (
                                        "python3 methods/swing_eval/analysis/mt5_next_action_run.py --target mt5_optimization "
                                        "--execute --allow-non-tester-primary"
                                    ),
                                    "runner_requires_allow_non_tester_primary": True,
                                    "primary_execution_class": "mt5_optimization_recommendation_refresh",
                                }
                            ],
                            "advisory_prior_action_count": 1,
                            "advisory_prior_actions": [
                                {
                                    "priority": 1,
                                    "area": "bridge",
                                    "action": "restore_bridge",
                                    "reason": "EA posting is stale.",
                                    "execution_kind": "bridge_status_refresh",
                                    "command_text": "python3 methods/swing_eval/analysis/bridge_status.py",
                                }
                            ],
                        }
                    }
                )
                + "\n",
                encoding="utf-8",
            )

            summary = artifact_summary(
                root,
                "mt5_tester_status",
                "runtime/latest_mt5_tester_status.json",
                now_epoch=time.time(),
                max_age_seconds=3600,
            )

        self.assertEqual(summary["next_action_runner_blocking_prior_action_count"], 1)
        self.assertEqual(summary["next_action_runner_blocking_prior_action_summary"], "P1 bridge:restore_bridge")
        self.assertEqual(summary["next_action_runner_blocking_prior_actions"][0]["reason"], "EA posting is stale.")
        self.assertEqual(
            summary["next_action_runner_blocking_prior_actions"][0]["runner_execute_hint"],
            (
                "python3 methods/swing_eval/analysis/mt5_next_action_run.py --target mt5_optimization "
                "--execute --allow-non-tester-primary"
            ),
        )
        self.assertTrue(
            summary["next_action_runner_blocking_prior_actions"][0][
                "runner_requires_allow_non_tester_primary"
            ]
        )
        self.assertEqual(
            summary["next_action_runner_blocking_prior_actions"][0]["primary_execution_class"],
            "mt5_optimization_recommendation_refresh",
        )
        self.assertEqual(summary["next_action_runner_advisory_prior_action_count"], 1)
        self.assertEqual(summary["next_action_runner_advisory_prior_action_summary"], "P1 bridge:restore_bridge")
        self.assertEqual(summary["next_action_runner_advisory_prior_actions"][0]["reason"], "EA posting is stale.")

    def test_spec_artifact_summary_extracts_manual_queue_stale_entries(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            queue_path = root / "runtime" / "latest_mt5_manual_test_queue.json"
            queue_path.parent.mkdir(parents=True, exist_ok=True)
            queue_path.write_text(
                json.dumps(
                    {
                        "status": "stale_runner_artifacts",
                        "entry_count": 0,
                        "total_entry_count": 1,
                        "stale_entry_count": 1,
                        "entries": [
                            {
                                "id": "score_weight_buy",
                                "title": "BUY Score Weight Sample Collection",
                                "source_json": "runtime/latest_mt5_next_action_run_buy.json",
                                "available": False,
                                "current_for_execution": False,
                                "gate_stale_reason": "selected_action_mismatch",
                                "stale_reasons": [
                                    "current_for_execution_false:selected_action_mismatch"
                                ],
                                "refresh_command_text": (
                                    "python3 methods/swing_eval/analysis/mt5_next_action_run.py --focus-side buy"
                                ),
                                "runner_generated_at": "2026.07.14 12:20",
                                "promotion_generated_at": "2026.07.14 12:01",
                                "current_promotion_generated_at": "2026.07.14 12:40",
                                "current_promotion_decision": "not_ready",
                            }
                        ],
                    }
                )
                + "\n",
                encoding="utf-8",
            )

            summary = artifact_summary(
                root,
                "mt5_manual_test_queue",
                "runtime/latest_mt5_manual_test_queue.json",
                now_epoch=time.time(),
                max_age_seconds=3600,
            )

        self.assertEqual(summary["status"], "stale_runner_artifacts")
        self.assertEqual(summary["stale_entry_count"], 1)
        self.assertEqual(summary["manual_queue_entries"], [])
        self.assertEqual(summary["manual_queue_stale_entries"][0]["id"], "score_weight_buy")
        self.assertFalse(summary["manual_queue_stale_entries"][0]["current_for_execution"])
        self.assertEqual(
            summary["manual_queue_stale_entries"][0]["stale_reasons"],
            ["current_for_execution_false:selected_action_mismatch"],
        )
        self.assertIn("--focus-side buy", summary["manual_queue_stale_entries"][0]["refresh_command_text"])
        self.assertEqual(summary["manual_queue_current_for_execution_count"], 0)
        self.assertEqual(summary["manual_queue_selected_action_current_count"], 0)
        self.assertEqual(summary["manual_queue_current_promotion_generated_at_values"], ["2026.07.14 12:40"])
        self.assertEqual(summary["manual_queue_current_promotion_decision_values"], ["not_ready"])
