    def test_bridge_recovery_plan_requests_history_refresh_when_history_data_is_stale(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            bridge_status_path = root / "latest_bridge_status.json"
            history_status_path = root / "latest_history_status.json"
            bridge_status_path.write_text(
                json.dumps(
                    {
                        "ok": True,
                        "operational_status": "ready",
                        "health": {"ok": True},
                        "config": {"ok": True},
                        "process": {"running": True},
                        "mt5_terminal": {"running": True, "match_count": 1},
                        "latest_snapshot": {
                            "fresh": True,
                            "age_seconds": 15.0,
                            "server_time": "2026.07.17 05:00",
                        },
                        "history_request": {
                            "pending": False,
                            "stale_pending": False,
                            "done_matches_request": True,
                            "request": {"id": "request-id"},
                            "done": {"id": "request-id"},
                        },
                        "bridge_log": {"activity": {"status": "ea_snapshot_post_recent"}},
                    }
                )
                + "\n",
                encoding="utf-8",
            )
            history_status_path.write_text(
                json.dumps(
                    {
                        "ok": True,
                        "server_time": "2026.07.16 00:00:00",
                        "timeframes": {"M1": {"last_time": "2026.07.16 00:00"}},
                    }
                )
                + "\n",
                encoding="utf-8",
            )

            plan = build_bridge_recovery_plan(
                bridge_status_path=bridge_status_path,
                history_status_path=history_status_path,
                now=datetime(2026, 7, 17, 5, 0, 0),
            )

        self.assertFalse(plan["ok"])
        self.assertEqual(plan["status"], "needs_history_refresh")
        self.assertFalse(plan["ready_for_mt5_validation"])
        self.assertEqual(plan["next_action"], "request_fresh_168h_history_and_wait_for_matching_done")
        self.assertIn("history_data_stale", plan["blocking_reasons"])
        self.assertFalse(plan["checks"]["history_data_fresh"])
        self.assertTrue(plan["checks"]["history_data_stale"])
        self.assertGreater(plan["checks"]["history_status_server_time_age_seconds"], 12 * 60 * 60)
        self.assertEqual(plan["operation_cards"][0]["area"], "history")
        self.assertTrue(plan["operation_cards"][0]["history_data_stale"])
        self.assertFalse(plan["operator_summary"]["history_data_fresh"])
        commands = {command["label"]: command["command"] for command in plan["commands"]}
        self.assertEqual(commands["request_history"], "python3 src/bridge/request_history.py 168")
        self.assertIn("methods/swing_eval/analysis/history_status.py", commands["refresh_history_status"])
        markdown = format_bridge_recovery_markdown(plan)
        self.assertIn("Status: needs_history_refresh", markdown)
        self.assertIn("Blocking reasons: history_data_stale", markdown)
        self.assertIn("History data is stale", markdown)
        self.assertIn("History data fresh: False stale=True", markdown)

