    def test_bridge_status_watch_can_refresh_history_status_before_recovery_plan(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            status_json = root / "latest_bridge_status.json"
            status_md = root / "latest_bridge_status.md"
            history_json = root / "latest_history_168h.json"
            history_done = root / "history_request.done.json"
            history_status = root / "latest_history_status.json"
            history_status_md = root / "latest_history_status.md"
            recovery_json = root / "latest_bridge_recovery_plan.json"
            recovery_md = root / "latest_bridge_recovery_plan.md"
            heartbeat = root / "bridge_status_watch_heartbeat.json"
            pid_file = root / "bridge_status_watch.pid"
            status_json.write_text(
                json.dumps(
                    {
                        "ok": False,
                        "operational_status": "ea_not_posting",
                        "health": {"ok": True, "status": 200},
                        "config": {"ok": True, "payload": {"history_request_id": "request-id"}},
                        "process": {"running": True, "match_count": 1},
                        "mt5_terminal": {"running": True, "match_count": 1},
                        "history_request": {
                            "pending": False,
                            "stale_pending": False,
                            "done_matches_request": True,
                            "request": {"id": "request-id"},
                            "done": {"id": "request-id"},
                        },
                    }
                )
                + "\n",
                encoding="utf-8",
            )
            history_status_payload = {
                "ok": True,
                "generated_at": "2026.07.18 09:00",
                "path": str(history_json),
                "symbol": "XAUUSD-m",
                "server_time": "2026.07.18 08:59:00",
                "history_hours": 168,
                "timeframes": {
                    "M1": {
                        "bars": 10080,
                        "expected_bars": 10080,
                        "complete": True,
                        "last_time": "2026.07.18 08:59",
                    }
                },
                "done": {
                    "exists": True,
                    "id": "request-id",
                    "source_server_time": "2026.07.18 08:59:00",
                },
            }
            recovery_json.write_text(
                json.dumps(
                    {
                        "ok": True,
                        "status": "ready",
                        "ready_for_mt5_validation": True,
                        "operation_cards": [],
                        "operator_summary": {"status": "ready", "ready_for_mt5_validation": True},
                        "checks": {"bridge_status_loaded": True},
                    }
                )
                + "\n",
                encoding="utf-8",
            )

            def fake_run(command, text, capture_output):
                self.assertTrue(text)
                self.assertTrue(capture_output)
                if "methods/swing_eval/analysis/history_status.py" in command:
                    history_status.write_text(
                        json.dumps(history_status_payload) + "\n",
                        encoding="utf-8",
                    )
                    history_status_md.write_text("# History Status\n", encoding="utf-8")
                    return subprocess.CompletedProcess(command, 0, stdout='{"ok": true}\n', stderr="")
                if "methods/swing_eval/analysis/bridge_status.py" in command:
                    return subprocess.CompletedProcess(command, 2, stdout='{"ok": false}\n', stderr="")
                if "methods/swing_eval/analysis/bridge_recovery_plan.py" in command:
                    return subprocess.CompletedProcess(command, 0, stdout='{"ok": true}\n', stderr="")
                raise AssertionError(f"unexpected command: {command}")

            with patch("analysis.bridge_status_watch.subprocess.run", side_effect=fake_run) as run:
                returncode = bridge_status_watch_main(
                    [
                        "--max-runs",
                        "1",
                        "--output-json",
                        str(status_json),
                        "--output-md",
                        str(status_md),
                        "--refresh-history-status",
                        "--history-json",
                        str(history_json),
                        "--history-done",
                        str(history_done),
                        "--history-status",
                        str(history_status),
                        "--history-status-md",
                        str(history_status_md),
                        "--recovery-output-json",
                        str(recovery_json),
                        "--recovery-output-md",
                        str(recovery_md),
                        "--heartbeat",
                        str(heartbeat),
                        "--pid-file",
                        str(pid_file),
                    ]
                )

            payload = json.loads(heartbeat.read_text(encoding="utf-8"))
            calls = [call.args[0] for call in run.call_args_list]

        self.assertEqual(returncode, 0)
        self.assertEqual(len(calls), 3)
        self.assertIn("methods/swing_eval/analysis/bridge_status.py", calls[0])
        self.assertIn("methods/swing_eval/analysis/history_status.py", calls[1])
        self.assertIn("methods/swing_eval/analysis/bridge_recovery_plan.py", calls[2])
        self.assertTrue(payload["history_status_refresh_enabled"])
        self.assertEqual(payload["history_status_refresh_status"], "refreshed")
        self.assertEqual(payload["history_status_refresh_returncode"], 0)
        self.assertTrue(payload["history_status_ok"])
        self.assertEqual(payload["history_status_generated_at"], "2026.07.18 09:00")
        self.assertEqual(payload["history_status_server_time"], "2026.07.18 08:59:00")
        self.assertEqual(payload["history_status_m1_bars"], 10080)
        self.assertEqual(payload["history_status_m1_last_time"], "2026.07.18 08:59")
        self.assertEqual(payload["history_status_done_id"], "request-id")

    def test_bridge_status_watch_one_shot_does_not_clobber_daemon_state_by_default(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            status_json = root / "latest_bridge_status.json"
            status_md = root / "latest_bridge_status.md"
            history_status = root / "latest_history_status.json"
            recovery_json = root / "latest_bridge_recovery_plan.json"
            recovery_md = root / "latest_bridge_recovery_plan.md"
            shared_heartbeat = root / "bridge_status_watch_heartbeat.json"
            shared_pid = root / "bridge_status_watch.pid"
            shared_heartbeat.write_text('{"continuous": true}\n', encoding="utf-8")
            shared_pid.write_text("daemon-pid\n", encoding="utf-8")
            status_json.write_text(
                json.dumps(
                    {
                        "ok": True,
                        "operational_status": "ok",
                        "health": {"ok": True},
                        "config": {"ok": True, "payload": {}},
                    }
                )
                + "\n",
                encoding="utf-8",
            )
            history_status.write_text(json.dumps({"ok": True}) + "\n", encoding="utf-8")

            completed = subprocess.CompletedProcess(
                args=["python3", "methods/swing_eval/analysis/bridge_status.py"],
                returncode=0,
                stdout='{"ok": true}\n',
                stderr="",
            )

            with patch("analysis.bridge_status_watch.DEFAULT_HEARTBEAT", str(shared_heartbeat)), patch(
                "analysis.bridge_status_watch.DEFAULT_PID_FILE",
                str(shared_pid),
            ), patch("analysis.bridge_status_watch.subprocess.run", return_value=completed):
                returncode = bridge_status_watch_main(
                    [
                        "--max-runs",
                        "1",
                        "--output-json",
                        str(status_json),
                        "--output-md",
                        str(status_md),
                        "--history-status",
                        str(history_status),
                        "--recovery-output-json",
                        str(recovery_json),
                        "--recovery-output-md",
                        str(recovery_md),
                        "--skip-recovery-plan",
                    ]
                )

            heartbeat_text = shared_heartbeat.read_text(encoding="utf-8")
            pid_text = shared_pid.read_text(encoding="utf-8")

        self.assertEqual(returncode, 0)
        self.assertEqual(heartbeat_text, '{"continuous": true}\n')
        self.assertEqual(pid_text, "daemon-pid\n")

    def test_runtime_watchers_start_missing_watcher_and_report_outputs(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            spec = WatcherSpec(
                name="bridge_status",
                script="methods/swing_eval/analysis/bridge_status_watch.py",
                heartbeat=str(root / "bridge_status_watch_heartbeat.json"),
                pid_file=str(root / "bridge_status_watch.pid"),
                log_file=str(root / "bridge_status_watch.log"),
                extra_args=("--output-json", str(root / "latest_bridge_status.json")),
            )

            class FakeProcess:
                pid = 4567

            def fake_popen(command, stdout, stderr, start_new_session):
                self.assertEqual(command[:4], ["python3", "methods/swing_eval/analysis/bridge_status_watch.py", "--interval-seconds", "60"])
                self.assertEqual(stderr, subprocess.STDOUT)
                self.assertTrue(start_new_session)
                self.assertFalse(stdout.closed)
                return FakeProcess()

            with patch("analysis.runtime_watchers.subprocess.Popen", side_effect=fake_popen):
                payload = build_runtime_watchers_summary(
                    specs=(spec,),
                    interval_seconds=60,
                    python_executable="python3",
                )

        self.assertTrue(payload["ok"])
        self.assertEqual(payload["watcher_count"], 1)
        row = payload["watchers"][0]
        self.assertEqual(row["status"], "started")
        self.assertEqual(row["started_pid"], 4567)
        self.assertIn("--heartbeat", row["command"])
        self.assertEqual(
            row["start_command_text"],
            "python3 methods/swing_eval/analysis/runtime_watchers.py --only bridge_status --interval-seconds 60 --max-heartbeat-age-seconds 180",
        )
        self.assertEqual(
            row["restart_command_text"],
            "python3 methods/swing_eval/analysis/runtime_watchers.py --only bridge_status --interval-seconds 60 --restart --max-heartbeat-age-seconds 180",
        )
        self.assertIn("tail -200", row["tail_log_command_text"])
        self.assertIn(str(root / "bridge_status_watch.log"), row["tail_log_command_text"])
        markdown = format_runtime_watchers_markdown(payload)
        self.assertIn("# Runtime Watchers", markdown)
        self.assertIn("| bridge_status | started |", markdown)
        self.assertIn(str(root / "bridge_status_watch.log"), markdown)
        self.assertIn("restart=`python3 methods/swing_eval/analysis/runtime_watchers.py --only bridge_status --interval-seconds 60 --restart --max-heartbeat-age-seconds 180`", markdown)
        self.assertIn("log=`tail -200", markdown)

