    def test_spec_coverage_reports_runtime_watchers_action_required(self):
        artifacts = [
            {"name": "bridge_status", "path": "runtime/latest_bridge_status.json", "exists": True, "fresh": True, "operational_status": "ready"},
            {
                "name": "runtime_watchers",
                "path": "runtime/latest_runtime_watchers.json",
                "exists": True,
                "fresh": True,
                "ok": False,
                "action_required_watcher_count": 1,
                "stale_watcher_count": 0,
                "max_heartbeat_age_seconds": 180,
                "runtime_watcher_action_required_summaries": [
                    {
                        "name": "bridge_status",
                        "status": "stale_pid_would_start",
                        "error": "pid file points to non-running process: 1234",
                        "heartbeat_status": "",
                        "heartbeat_fresh": False,
                        "heartbeat_age_seconds": "",
                        "schema_ok": False,
                        "missing_required_field_count": 0,
                        "restart_command_text": (
                            "python3 methods/swing_eval/analysis/runtime_watchers.py --only bridge_status "
                            "--interval-seconds 60 --restart --max-heartbeat-age-seconds 180"
                        ),
                        "tail_log_command_text": "tail -200 runtime/bridge_status_watch.log",
                    }
                ],
            },
        ]

        reasons = completion_reasons(components=[], artifacts=artifacts, mql5_artifacts=[])
        actions = build_spec_next_actions(workspace=Path("/tmp"), artifacts=artifacts, reasons=reasons)

        self.assertIn("runtime_watchers_not_ready:ok_false", reasons)
        self.assertIn("runtime_watchers_action_required:1", reasons)
        action = next(item for item in actions if item["id"] == "refresh_runtime_watchers")
        commands = {command["label"]: command["command"] for command in action["commands"]}
        self.assertEqual(
            commands["restart_bridge_status"],
            "python3 methods/swing_eval/analysis/runtime_watchers.py --only bridge_status "
            "--interval-seconds 60 --restart --max-heartbeat-age-seconds 180",
        )
        self.assertEqual(commands["tail_log_bridge_status"], "tail -200 runtime/bridge_status_watch.log")
        self.assertIn("Action required watcher count: 1", action["manual_steps"])
        self.assertTrue(
            any(
                "Runtime watcher detail: bridge_status" in step
                and "stale_pid_would_start" in step
                and "tail -200 runtime/bridge_status_watch.log" in step
                for step in action["manual_steps"]
            )
        )
        self.assertIn(
            "If stale, missing, or action-required watcher state persists, rerun with --restart.",
            action["manual_steps"],
        )

    def test_promotion_gate_blocks_when_bridge_status_is_not_ready(self):
        bridge_status = {
            "ok": False,
            "operational_status": "ea_not_posting",
            "next_action": "attach EA",
            "health_ok": True,
            "config_ok": True,
            "config_history_hours": 168,
            "config_history_request_id": "pending-id",
            "snapshot_fresh": False,
            "snapshot_age_seconds": 999,
            "snapshot_server_time": "2026.07.13 21:00",
            "history_request_pending": True,
            "history_request_stale_pending": True,
            "history_request_pending_age_seconds": 500,
            "bridge_log_activity_status": "ea_post_stale",
            "ea_liveness_signal": "config_get_only_not_liveness",
            "config_get_recent": True,
            "ea_post_recent": False,
            "config_get_recent_but_ea_post_stale": True,
            "bridge_log_ea_post_count": 12,
            "bridge_log_last_ea_post_at": "13/Jul/2026 21:00:30",
            "bridge_log_last_ea_post_age_seconds": 570.0,
            "bridge_log_last_snapshot_post_at": "13/Jul/2026 21:00:30",
            "bridge_log_last_snapshot_post_age_seconds": 570.0,
            "mt5_terminal_running": True,
            "mt5_terminal_match_count": 1,
            "ea_attention_required": True,
            "ea_attention_reason": "mt5_terminal_running_but_ea_post_stale",
            "bridge_log_ea_liveness_signal": "config_get_only_not_liveness",
            "bridge_log_config_get_recent": True,
            "bridge_log_ea_post_recent": False,
            "bridge_log_config_get_recent_but_ea_post_stale": True,
        }

        checks = promotion_checks(
            history_hours=168,
            history_timeframes={"M1": 10080, "M5": 2016, "M15": 672, "M30": 336},
            summary={"overall": {"count": 100, "avg_r": 0.1, "pf": 1.3, "max_losing_streak": 2}, "side": []},
            audit={"passed": True, "fresh": True, "command": {"score": 60, "spread_limit_points": 30, "lot": 0.1}},
            forward_summary={"closed": 30, "avg_r": 0.1, "pf": 1.3, "max_drawdown_r": 0.0},
            bridge_status_summary=bridge_status,
            min_history_hours=168,
            min_candidates=100,
            min_avg_r=0.0,
            min_pf=1.2,
            max_losing_streak_allowed=20,
            min_side_count=0,
            min_side_pf=1.0,
            min_side_avg_r=0.0,
            require_dry_run_passed=False,
            max_dry_run_age_seconds=3600,
            require_forward=False,
            min_forward_closed=30,
            min_forward_avg_r=0.0,
            min_forward_pf=1.2,
        )
        by_name = {row["name"]: row for row in checks}
        self.assertFalse(by_name["bridge_status_ready"]["passed"])
        self.assertEqual(
            by_name["bridge_status_ready"]["value"]["ea_liveness_signal"],
            "config_get_only_not_liveness",
        )
        self.assertTrue(by_name["bridge_status_ready"]["value"]["config_get_recent_but_ea_post_stale"])
        report = {
            "decision": "not_ready",
            "live_ready": False,
            "generated_at": "2026.07.13 22:00",
            "checks": checks,
            "summary": {"overall": {}},
            "forward_test": {},
            "bridge_status": bridge_status,
        }

        actions = build_promotion_next_actions(report)
        action = next(item for item in actions if item["area"] == "bridge")
        markdown = format_promotion_markdown({**report, "next_actions": actions})

        self.assertEqual(action["priority"], 1)
        self.assertEqual(action["action"], "restore_mt5_ai_bridge_ea_posting_before_history_refresh")
        self.assertIn("methods/swing_eval/analysis/bridge_status.py", action["evidence"]["execution"]["command_text"])
        self.assertIn("methods/swing_eval/analysis/bridge_status_watch.py", action["evidence"]["execution"]["watch_command_text"])
        self.assertIn("methods/swing_eval/analysis/bridge_recovery_plan.py", action["evidence"]["execution"]["recovery_plan_command_text"])
        self.assertIn("## Bridge Status", markdown)
        self.assertIn("Operational status: ea_not_posting", markdown)
        self.assertIn("Config history request: hours=168, id=pending-id", markdown)
        self.assertIn("Bridge log activity: status=ea_post_stale", markdown)
        self.assertIn("Bridge EA liveness: signal=config_get_only_not_liveness", markdown)
        self.assertIn("config_get_recent_but_ea_post_stale=True", markdown)
        self.assertIn("Bridge config GET: last_config_get=", markdown)
        self.assertIn("GET /config may be produced by status checks", markdown)
        self.assertIn("Bridge EA attention: required=True", markdown)
        self.assertIn("reason=mt5_terminal_running_but_ea_post_stale", markdown)
        self.assertIn("recovery_plan: python3 methods/swing_eval/analysis/bridge_recovery_plan.py", markdown)
        self.assertIn("snapshot_post_age_seconds=570.0", markdown)

    def test_score_weight_sample_collection_execution_plan_uses_side_specific_outputs(self):
        sell_plan = score_weight_sample_collection_execution_plan(focus_side="sell", archive_run_id="run_sell")
        buy_plan = score_weight_sample_collection_execution_plan(focus_side="buy", archive_run_id="run_buy")
        fallback_plan = score_weight_sample_collection_execution_plan(focus_side="invalid", archive_run_id="run_both")
        archive_plan = mt5_agent_csv_archive_execution_plan(execute=False, run_id="run_sell")

        self.assertEqual(sell_plan["focus_side"], "sell")
        self.assertEqual(sell_plan["report_name"], r"Tester\Swing_Evaluation_Trader_sample_collection_sell")
        self.assertEqual(
            sell_plan["outputs"]["run_json"],
            "runtime/latest_mt5_tester_sample_collection_sell_run.json",
        )
        self.assertEqual(
            sell_plan["outputs"]["optimization_json"],
            "runtime/latest_mt5_sample_collection_sell_report.json",
        )
        self.assertIn("--focus-side sell", sell_plan["command_text"])
        self.assertIn("--sync-expert-parameters-set", sell_plan["command_text"])
        self.assertIn("Swing_Evaluation_Trader_sample_collection_sell", sell_plan["command_text"])
        self.assertEqual(buy_plan["focus_side"], "buy")
        self.assertEqual(
            buy_plan["outputs"]["run_json"],
            "runtime/latest_mt5_tester_sample_collection_buy_run.json",
        )
        self.assertNotEqual(sell_plan["outputs"]["run_json"], buy_plan["outputs"]["run_json"])
        self.assertEqual(fallback_plan["focus_side"], "both")
        self.assertEqual(
            fallback_plan["outputs"]["run_json"],
            "runtime/latest_mt5_tester_sample_collection_both_run.json",
        )
        self.assertEqual(
            archive_plan["outputs"]["json"],
            "runtime/latest_mt5_agent_csv_archive.json",
        )

    def test_detect_swings_finds_confirmed_high_and_low(self):
        bars = [
            bar(0, 10, 10, 9, 9.5),
            bar(1, 9.5, 11, 9, 10.5),
            bar(2, 10.5, 13, 10, 12),
            bar(3, 12, 11.5, 9.5, 10),
            bar(4, 10, 10.5, 8, 8.5),
            bar(5, 8.5, 9, 7, 8),
            bar(6, 8, 9.5, 7.8, 9),
        ]
        atr = [1.0] * len(bars)
        swings = detect_swings(bars, atr, left=1, right=1, min_atr_distance=0.1)
        self.assertEqual([(s.kind, s.index) for s in swings], [("high", 2), ("low", 5)])

    def test_swing_report_rows_include_non_repaint_confirmation_time(self):
        bars = [
            bar(0, 10, 10, 9, 9.5),
            bar(1, 9.5, 11, 9, 10.5),
            bar(2, 10.5, 13, 10, 12),
            bar(3, 12, 11.5, 9.5, 10),
            bar(4, 10, 10.5, 8, 8.5),
            bar(5, 8.5, 9, 7, 8),
            bar(6, 8, 9.5, 7.8, 9),
        ]
        history = MarketHistory(
            symbol="XAUUSD-m",
            server_time=bars[-1].time_text,
            history_hours=1,
            point=0.01,
            spread_points=37,
            timeframes={"M1": bars},
            indicators={"M1": {"atr14": [1.0] * len(bars)}},
        )

        rows = swing_report_rows(history, timeframes=("M1",), left=1, right=1, min_atr_distance=0.1)
        summary = swing_summary_rows(rows)

        self.assertEqual(rows[0]["kind"], "high")
        self.assertEqual(rows[0]["swing_time"], bars[2].time_text)
        self.assertEqual(rows[0]["confirmed_time"], bars[3].time_text)
        self.assertEqual(rows[0]["confirmed_after_bars"], 1)
        self.assertEqual(summary[0]["count"], 1)

