    def test_score_weight_set_writer_preserves_existing_output_when_skipped(self):
        payload = {
            "ok": True,
            "top_weight_candidate": {"side": "buy", "threshold": 60, "trend_w": 1.5},
            "walk_forward": {
                "enabled": True,
                "aggregate": {"status": "walk_forward_candidate_failed"},
            },
        }
        with tempfile.TemporaryDirectory() as tmpdir:
            template_path = Path(tmpdir) / "template.set"
            output_path = Path(tmpdir) / "output.set"
            template_path.write_text("InpMinScore=50||50||1||50||N\n", encoding="utf-8")
            output_path.write_text("keep existing\n", encoding="utf-8")

            metadata = write_score_weight_set(output_path, template_path, payload)

            self.assertFalse(metadata["written"])
            self.assertFalse(metadata["decision"]["written"])
            self.assertEqual(metadata["decision"]["output_set"], str(output_path))
            self.assertEqual(output_path.read_text(encoding="utf-8"), "keep existing\n")

    def test_weight_search_walk_forward_returns_fold_and_aggregate_evidence(self):
        candidates: list[Candidate] = []
        results: list[BacktestResult] = []
        for index in range(12):
            candidate = candidate_with_score(
                f"wf-{index}",
                4,
                trend=20 if index % 3 == 0 else 8,
                structure=10,
                entry=10,
                risk_score=12,
                cost=-1,
                chop=-1,
            )
            candidate.index = index
            candidate.time = datetime(2026, 7, 7, 0, 0) + timedelta(minutes=index)
            candidate.time_text = candidate.time.strftime("%Y.%m.%d %H:%M")
            candidates.append(candidate)
            net_r = 4.0 if index % 3 == 0 else -1.0
            results.append(
                BacktestResult(
                    candidate_id=candidate.candidate_id,
                    result="win" if net_r > 0 else "loss",
                    r_multiple=net_r,
                    net_r_multiple=net_r,
                    exit_time=candidate.time_text,
                    exit_price=candidate.entry,
                    exit_reason="tp" if net_r > 0 else "sl",
                    bars_held=1,
                )
            )

        walk = weight_search_walk_forward(
            candidates,
            results,
            side="both",
            min_count=2,
            folds=2,
            train_window=6,
            test_window=3,
        )

        self.assertTrue(walk["enabled"])
        self.assertEqual(len(walk["fold_rows"]), 2)
        aggregate = walk["aggregate"]
        self.assertIn("walk_forward_candidate", aggregate["status"])
        self.assertEqual(aggregate["folds"], 2)
        self.assertIn("mean_test_weight_avg_r", aggregate)

