    def test_regime_weight_search_returns_group_rows_with_walk_forward(self):
        candidates: list[Candidate] = []
        results: list[BacktestResult] = []
        for index in range(16):
            candidate = candidate_with_score(
                f"regime-{index}",
                4,
                trend=20 if index % 2 == 0 else 8,
                structure=10,
                entry=10,
                risk_score=12,
                cost=-1,
                chop=-1,
            )
            candidate.time = datetime(2026, 7, 7, 12 if index < 8 else 13, index % 60)
            candidate.time_text = candidate.time.strftime("%Y.%m.%d %H:%M")
            if index < 8:
                candidate.features.update({"M30_ema_fast": 99.0, "M30_ema_slow": 100.0, "M15_ema_fast": 99.0, "M15_ema_slow": 100.0})
            else:
                candidate.features.update({"M30_ema_fast": 101.0, "M30_ema_slow": 100.0, "M15_ema_fast": 101.0, "M15_ema_slow": 100.0})
            candidates.append(candidate)
            net_r = 4.0 if index % 2 == 0 else -1.0
            results.append(
                BacktestResult(
                    candidate_id=candidate.candidate_id,
                    result="win" if net_r > 0 else "loss",
                    r_multiple=net_r,
                    net_r_multiple=net_r,
                    exit_time=candidate.time_text,
                    exit_price=candidate.entry,
                    exit_reason="tp" if net_r > 0 else "sl",
                    bars_held=1,
                )
            )

        search = regime_weight_search(
            candidates,
            results,
            side="sell",
            regimes=["entry_hour", "m30_m15_trend"],
            min_count=4,
            top_per_group=1,
            walk_forward=True,
            wf_folds=2,
            wf_train_window=4,
            wf_test_window=2,
        )

        self.assertTrue(search["enabled"])
        self.assertGreaterEqual(search["row_count"], 4)
        rows = {(row["dimension"], row["group"]): row for row in search["rows"]}
        self.assertIn(("entry_hour", "12:00-13:00"), rows)
        self.assertIn(("m30_m15_trend", "M30 down M15 down"), rows)
        self.assertIn("baseline", rows[("entry_hour", "12:00-13:00")])
        self.assertTrue(rows[("entry_hour", "12:00-13:00")]["walk_forward"]["enabled"])
        self.assertIn("best_regime_candidate", search)

    def test_history_status_validates_full_timeframes_and_warns_about_preview_bars(self):
        def raw_bars(count: int) -> list[dict[str, object]]:
            return [{"time": f"2026.07.07 00:{i % 60:02d}:00", "open": 1, "high": 1, "low": 1, "close": 1} for i in range(count)]

        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            history_path = root / "history.json"
            done_path = root / "done.json"
            history_path.write_text(
                json.dumps(
                    {
                        "symbol": "XAUUSD-m",
                        "server_time": "2026.07.07 02:00:00",
                        "history_hours": 2,
                        "bars": raw_bars(2),
                        "timeframes": {
                            "M1": {"bars": raw_bars(120)},
                            "M5": {"bars": raw_bars(24)},
                            "M15": {"bars": raw_bars(8)},
                            "M30": {"bars": raw_bars(4)},
                        },
                    }
                ),
                encoding="utf-8",
            )
            done_path.write_text(
                json.dumps({"id": "req-1", "hours": 2, "bars": {"M1": 120, "M5": 24, "M15": 8, "M30": 4}}),
                encoding="utf-8",
            )

            status = history_status(history_path, done_path=done_path)
            markdown = format_history_status_markdown(status)

        self.assertTrue(status["ok"])
        self.assertEqual(status["top_level_bars"], 2)
        self.assertEqual(status["analysis_bar_source"], "timeframes.M1.bars")
        self.assertEqual(status["timeframes"]["M1"]["bars"], 120)
        self.assertTrue(any("compact preview" in warning for warning in status["warnings"]))
        self.assertIn("| M1 | 120 | 120 | 1.0 | True |", markdown)

    def test_history_status_rejects_missing_full_timeframe_bars(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            history_path = Path(tmpdir) / "history.json"
            history_path.write_text(
                json.dumps({"symbol": "XAUUSD-m", "history_hours": 1, "bars": [{"time": "2026.07.07 00:00:00"}]}),
                encoding="utf-8",
            )

            status = history_status(history_path)

