    def test_rr_adoption_audit_rejects_variable_rr_side_concentration(self):
        summary_rows = [
            {
                "strategy": "fixed_1_3",
                "policy": "fixed",
                "side": "both",
                "count": 20,
                "avg_r": 0.2,
                "pf": 1.2,
                "total_r": 4.0,
                "max_drawdown_r": 2.0,
            },
            {
                "strategy": "variable_side_ladder",
                "policy": "side_ladder",
                "side": "both",
                "count": 20,
                "avg_r": 0.4,
                "pf": 1.8,
                "total_r": 8.0,
                "max_drawdown_r": 1.0,
            },
        ]
        threshold_rows = [
            {"strategy": "fixed_1_3", "threshold": 50.0, "count": 20, "avg_r": 0.2, "pf": 1.2},
            {"strategy": "fixed_1_3", "threshold": 60.0, "count": 10, "avg_r": 0.25, "pf": 1.3},
            {"strategy": "variable_side_ladder", "threshold": 50.0, "count": 20, "avg_r": 0.4, "pf": 1.8},
            {"strategy": "variable_side_ladder", "threshold": 60.0, "count": 10, "avg_r": 0.45, "pf": 2.0},
        ]
        detail_rows = [
            {
                "strategy": "variable_side_ladder",
                "candidate_id": f"sell-{index}",
                "side": "sell",
                "result": "win",
                "net_r_multiple": 1.0,
            }
            for index in range(9)
        ]
        detail_rows.append(
            {
                "strategy": "variable_side_ladder",
                "candidate_id": "buy-1",
                "side": "buy",
                "result": "loss",
                "net_r_multiple": -1.0,
            }
        )
        detail_rows.extend(
            [
                {
                    "strategy": "fixed_1_3",
                    "candidate_id": f"fixed-buy-{index}",
                    "side": "buy",
                    "result": "win",
                    "net_r_multiple": 0.2,
                }
                for index in range(5)
            ]
        )
        detail_rows.extend(
            [
                {
                    "strategy": "fixed_1_3",
                    "candidate_id": f"fixed-sell-{index}",
                    "side": "sell",
                    "result": "win",
                    "net_r_multiple": 0.2,
                }
                for index in range(5)
            ]
        )

        rows = rr_strategy_adoption_audit(summary_rows, threshold_rows, detail_rows)
        by_strategy = {row["strategy"]: row for row in rows}

        self.assertEqual(by_strategy["fixed_1_3"]["status"], "candidate")
        variable = by_strategy["variable_side_ladder"]
        self.assertEqual(variable["status"], "rejected")
        self.assertIn("buy_avg_r_negative", variable["reasons"])
        self.assertIn("positive_total_r_side_share_gt_0.85", variable["reasons"])
        self.assertEqual(variable["side_positive_share_side"], "sell")

        markdown = format_experiment_markdown(summary_rows, threshold_rows, [], rows)
        self.assertIn("## Adoption Audit", markdown)
        self.assertIn("variable_side_ladder", markdown)
        self.assertIn("positive_total_r_side_share_gt_0.85", markdown)

