    def test_build_features_uses_only_confirmed_m5_swings_for_tp_obstacles(self):
        m1 = [bar(i, 100, 101, 99, 100) for i in range(40)]
        m5 = [
            bar(0, 100, 101, 99, 100),
            bar(5, 100, 102, 99, 101),
            bar(10, 101, 103, 100, 102),
            bar(15, 102, 105, 98, 100),
            bar(20, 100, 103, 99, 101),
            bar(25, 101, 100, 94, 96),
            bar(30, 96, 101, 96, 99),
            bar(35, 99, 102, 97, 100),
        ]
        history = MarketHistory(
            symbol="XAUUSD-m",
            server_time=m1[-1].time_text,
            history_hours=1,
            point=0.01,
            spread_points=0,
            timeframes={"M1": m1, "M5": m5},
            indicators={
                "M1": {"atr14": [1.0] * len(m1), "ema_fast": [100.0] * len(m1)},
                "M5": {
                    "atr14": [2.0] * len(m5),
                    "ema_fast": [100.0] * len(m5),
                    "ema_slow": [99.0] * len(m5),
                    "ema_mid": [100.0] * len(m5),
                    "ema_long": [99.0] * len(m5),
                    "rsi14": [55.0] * len(m5),
                },
            },
        )
        early = candidate_at(m1, 20, "buy", entry=100, sl=99, tp=106)
        confirmed = candidate_at(m1, 35, "buy", entry=100, sl=99, tp=106)

        early_features = build_features(history, early, [], tp_obstacle_count=0, previous_swing_distance_atr=0)
        confirmed_features = build_features(history, confirmed, [], tp_obstacle_count=0, previous_swing_distance_atr=0)

        self.assertNotIn("M5_tp_obstacle_count", early_features)
        self.assertEqual(confirmed_features["M5_tp_obstacle_count"], 1)
        self.assertEqual(confirmed_features["M5_nearest_tp_obstacle_price"], 105)
        self.assertEqual(confirmed_features["M5_last_swing_high_time"], m5[3].time_text)
        self.assertEqual(confirmed_features["M5_last_swing_low_price"], 94)

