    def test_write_command_refuses_to_overwrite_pending_without_replace(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            path = Path(tmpdir) / "trade_command.json"
            path.write_text(json.dumps({"id": "old", "status": "pending"}), encoding="utf-8")

            with self.assertRaises(RuntimeError):
                write_command(path, {"id": "new", "status": "pending"})

            self.assertEqual(json.loads(path.read_text(encoding="utf-8"))["id"], "old")
            write_command(path, {"id": "new", "status": "pending"}, replace=True)

            self.assertEqual(json.loads(path.read_text(encoding="utf-8"))["id"], "new")

