    def test_risk_gate_rejects_daily_loss_and_consecutive_losses(self):
        deals = {
            "server_time": "2026.07.07 12:00:00",
            "deals": [
                {"ticket": 3, "symbol": "XAUUSD-m", "entry": "out", "profit": -700, "time": "2026.07.07 11:00:00"},
                {"ticket": 2, "symbol": "XAUUSD-m", "entry": "out", "profit": -600, "time": "2026.07.07 10:00:00"},
                {"ticket": 1, "symbol": "XAUUSD-m", "entry": "out", "profit": 100, "time": "2026.07.07 09:00:00"},
            ],
        }

        result = evaluate_risk_gate(
            deal_history_payload=deals,
            symbol="XAUUSD-m",
            daily_loss_limit=1000,
            consecutive_loss_limit=2,
        )

        self.assertFalse(result.allowed)
        self.assertEqual(result.metrics["daily_realized_pnl"], -1200.0)
        self.assertEqual(result.metrics["consecutive_losses"], 2)
        self.assertTrue(result.metrics["consecutive_loss_cooldown_active"])

    def test_risk_gate_allows_after_consecutive_loss_cooldown_expires(self):
        deals = {
            "server_time": "2026.07.07 13:01:00",
            "deals": [
                {"ticket": 3, "symbol": "XAUUSD-m", "entry": "out", "profit": -50, "time": "2026.07.07 11:00:00"},
                {"ticket": 2, "symbol": "XAUUSD-m", "entry": "out", "profit": -40, "time": "2026.07.07 10:00:00"},
                {"ticket": 1, "symbol": "XAUUSD-m", "entry": "out", "profit": 100, "time": "2026.07.07 09:00:00"},
            ],
        }

        result = evaluate_risk_gate(
            deal_history_payload=deals,
            symbol="XAUUSD-m",
            daily_loss_limit=1000,
            consecutive_loss_limit=2,
            consecutive_loss_cooldown_minutes=120,
        )

        self.assertTrue(result.allowed)
        self.assertEqual(result.metrics["consecutive_losses"], 2)
        self.assertEqual(result.metrics["consecutive_loss_cooldown_until"], "2026.07.07 13:00:00")
        self.assertFalse(result.metrics["consecutive_loss_cooldown_active"])

