        signal = {"action": "hold", "mode": "manual_review", "symbol": "XAUUSD-m"}

        audit = build_audit(signal=signal, command=command, trade_result=result, max_age_seconds=100, now_epoch=1000)

        self.assertEqual(audit["outcome"], "ea_dry_run_passed")
