    def test_dry_run_audit_classifies_rejected_command_before_ea(self):
        command = {
            "id": "cmd-2",
            "status": "rejected",
            "action": "hold",
            "dry_run": True,
            "created_at": 990,
            "reason": "signal action is not tradable",
            "source_signal": {
                "candidate_time": "2026.07.07 00:00",
                "latest_bar_time": "2026.07.07 00:01",
                "history_server_time": "2026.07.07 00:02",
                "generated_at": "2026.07.07 00:00:10",
                "valid_for_seconds": 120,
            },
        }

        audit = build_audit(
            signal={
                "action": "hold",
                "mode": "manual_review",
                "generated_at": "2026.07.07 00:00:10",
                "valid_for_seconds": 120,
            },
            command=command,
            trade_result={"id": "old", "status": "dry_run_passed", "dry_run": True, "received_at": 100},
            max_age_seconds=100,
            now_epoch=1000,
        )

        self.assertEqual(audit["outcome"], "blocked_before_ea")
        self.assertTrue(audit["freshness"]["fresh"])
        self.assertFalse(audit["freshness"]["result_required"])
        self.assertFalse(audit["trade_result"]["present"])
        self.assertEqual(audit["signal"]["generated_at"], "2026.07.07 00:00:10")
        self.assertEqual(audit["signal"]["valid_for_seconds"], 120)
        self.assertEqual(audit["command"]["source_generated_at"], "2026.07.07 00:00:10")
        self.assertEqual(audit["command"]["source_valid_for_seconds"], 120)
        self.assertEqual(audit["command"]["source_candidate_time"], "2026.07.07 00:00")
