    def test_forward_test_watch_records_evaluates_and_deduplicates_signal(self):
        signal = {
            "mode": "manual_review",
            "action": "buy",
            "symbol": "XAUUSD-m",
            "score": 61,
            "risk_reward": 3,
            "current_entry_reference": 100,
            "stop_loss": 99,
            "take_profit": 103,
            "latest_bar_time": "2026.07.07 00:00",
            "candidate_time": "2026.07.07 00:00",
        }
        history = {
            "symbol": "XAUUSD-m",
            "history_hours": 1,
            "point": 0.01,
            "spread_points": 20,
            "timeframes": {
                "M1": {
                    "bars": [
                        {"time": "2026.07.07 00:00", "open": 100, "high": 100.5, "low": 99.5, "close": 100},
                        {"time": "2026.07.07 00:01", "open": 100, "high": 101, "low": 99.8, "close": 100.5},
                        {"time": "2026.07.07 00:02", "open": 100.5, "high": 103.2, "low": 100.3, "close": 103},
                    ]
                }
            },
        }
        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            signal_path = root / "latest_signal.json"
            history_path = root / "history.json"
            ledger = root / "forward_tests.jsonl"
            signal_path.write_text(json.dumps(signal), encoding="utf-8")
            history_path.write_text(json.dumps(history), encoding="utf-8")

            heartbeat = refresh_forward_test_watch(
                signal_path=signal_path,
                ledger_path=ledger,
                history_path=history_path,
                summary_json=root / "latest_forward_test.json",
                summary_md=root / "latest_forward_test.md",
                status_json=root / "latest_forward_test_status.json",
                status_md=root / "latest_forward_test_status.md",
                heartbeat_path=root / "forward_test_watch_heartbeat.json",
            )
            second = refresh_forward_test_watch(
                signal_path=signal_path,
                ledger_path=ledger,
                history_path=history_path,
                summary_json=root / "latest_forward_test.json",
                summary_md=root / "latest_forward_test.md",
                status_json=root / "latest_forward_test_status.json",
                status_md=root / "latest_forward_test_status.md",
                heartbeat_path=root / "forward_test_watch_heartbeat.json",
            )
            records = read_records(ledger)
            status_payload = json.loads((root / "latest_forward_test_status.json").read_text(encoding="utf-8"))

        self.assertEqual(heartbeat["record_result"], "written")
        self.assertEqual(heartbeat["evaluation_result"], "evaluated")
        self.assertEqual(heartbeat["schema_version"], 2)
        self.assertEqual(
            heartbeat["implementation_version"],
            FORWARD_TEST_WATCH_HEARTBEAT_IMPLEMENTATION_VERSION,
        )
        self.assertEqual(
            heartbeat["snapshot_required_keys"],
            list(FORWARD_TEST_WATCH_HEARTBEAT_REQUIRED_FIELDS),
        )
        self.assertEqual(heartbeat["generated_at"], heartbeat["finished_at"])
        self.assertIn("status", heartbeat["snapshot_required_keys"])
        self.assertIn("returncode", heartbeat["snapshot_required_keys"])
        self.assertEqual(heartbeat["status"], "ok")
        self.assertEqual(heartbeat["returncode"], 0)
        self.assertIsInstance(heartbeat["started_epoch"], float)
        self.assertIsInstance(heartbeat["finished_epoch"], float)
        self.assertGreaterEqual(heartbeat["finished_epoch"], heartbeat["started_epoch"])
        self.assertGreaterEqual(heartbeat["elapsed_seconds"], 0.0)
        self.assertEqual(heartbeat["watcher_pid"], os.getpid())
        self.assertEqual(heartbeat["pid_file"], "")
        self.assertTrue(heartbeat["pid_file_written"])
        self.assertEqual(heartbeat["run_index"], 1)
        self.assertEqual(heartbeat["max_runs"], 1)
        self.assertFalse(heartbeat["continuous"])
        self.assertEqual(heartbeat["summary"]["closed"], 1)
        self.assertEqual(heartbeat["summary"]["wins"], 1)
        self.assertEqual(second["record_result"], "duplicate_not_written")
        self.assertEqual(len(records), 1)
        self.assertEqual(records[0]["status"], "closed")
        self.assertEqual(records[0]["outcome"], "win")
        self.assertEqual(status_payload["summary"]["closed"], 1)

