    def test_promotion_checks_require_forward_closed_samples(self):
        summary = {
            "overall": {"count": 120, "avg_r": 0.2, "pf": 1.4, "max_losing_streak": 4},
            "side": [
                {"group": "buy", "count": 60, "pf": 1.3},
                {"group": "sell", "count": 60, "pf": 1.2},
            ],
        }
        audit = {
            "outcome": "ea_dry_run_passed",
            "dry_run_only": True,
            "freshness": {"fresh": True},
            "signal_command_match": True,
            "signal_command": {"matched": True},
            "risk_gate": {"allowed": True, "reasons": [], "metrics": {"projected_volume": 0.1}},
        }
        forward = {"closed": 5, "avg_r": 0.3, "pf": 1.5}

        checks = promotion_checks(
            history_hours=168,
            summary=summary,
            audit=audit,
            forward_summary=forward,
            min_history_hours=168,
            min_candidates=100,
            min_avg_r=0.0,
            min_pf=1.2,
            max_losing_streak_allowed=8,
            min_side_count=30,
            min_side_pf=1.0,
            require_dry_run_passed=True,
            max_dry_run_age_seconds=3600,
            require_forward=True,
            min_forward_closed=30,
            min_forward_avg_r=0.0,
            min_forward_pf=1.2,
        )

        forward_count = next(item for item in checks if item["name"] == "forward_closed_count")
        self.assertFalse(forward_count["passed"])

