    def test_promotion_checks_reject_risk_gate_blocked_dry_run(self):
        summary = {
            "overall": {"count": 120, "avg_r": 0.2, "pf": 1.4, "max_losing_streak": 4},
            "side": [
                {"group": "buy", "count": 60, "pf": 1.3},
                {"group": "sell", "count": 60, "pf": 1.2},
            ],
        }
        audit = {
            "outcome": "ea_dry_run_passed",
            "dry_run_only": True,
            "freshness": {"fresh": True},
            "signal_command_match": True,
            "signal_command": {"matched": True},
            "risk_gate": {
                "allowed": False,
                "reasons": ["projected volume 0.40 exceeds limit 0.30"],
                "metrics": {"projected_volume": 0.4, "max_total_volume": 0.3},
            },
        }
        forward = {"closed": 30, "avg_r": 0.3, "pf": 1.5}

        checks = promotion_checks(
            history_hours=168,
            summary=summary,
            audit=audit,
            forward_summary=forward,
            min_history_hours=168,
            min_candidates=100,
            min_avg_r=0.0,
            min_pf=1.2,
            max_losing_streak_allowed=8,
            min_side_count=30,
            min_side_pf=1.0,
            require_dry_run_passed=True,
            max_dry_run_age_seconds=3600,
            require_forward=True,
            min_forward_closed=30,
            min_forward_avg_r=0.0,
            min_forward_pf=1.2,
        )
        report = {"checks": checks, "dry_run_audit": audit}
        actions = build_promotion_next_actions(report)

        risk_check = next(item for item in checks if item["name"] == "dry_run_risk_gate_allowed")
        self.assertFalse(risk_check["passed"])
        self.assertIn("projected volume", str(risk_check["value"]))
        self.assertTrue(
            any(action["action"] == "resolve_risk_gate_block_before_refreshing_dry_run" for action in actions)
        )
        self.assertFalse(any(action["action"] == "refresh_dry_run_with_current_signal" for action in actions))
        action = next(action for action in actions if action["action"] == "resolve_risk_gate_block_before_refreshing_dry_run")
        self.assertIn("projected volume", str(action["evidence"]["risk_gate"]["reasons"]))
        self.assertIn("methods/swing_eval/analysis/dry_run_command.py", action["evidence"]["execution"]["command_text"])
        self.assertIn("--write-rejections", action["evidence"]["execution"]["command_text"])
        self.assertIn("methods/swing_eval/analysis/dry_run_audit.py", action["evidence"]["execution"]["follow_up_command_text"])

