    def test_promotion_gate_marks_stale_forward_watch_heartbeat(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            heartbeat_path = Path(tmpdir) / "forward_test_watch_heartbeat.json"
            heartbeat_path.write_text(json.dumps({"next_run_in_seconds": 60}), encoding="utf-8")
            old_timestamp = datetime.now().timestamp() - 600
            os.utime(heartbeat_path, (old_timestamp, old_timestamp))

            heartbeat = load_watch_heartbeat(heartbeat_path)

        self.assertFalse(heartbeat["heartbeat_fresh"])
        self.assertEqual(heartbeat["heartbeat_max_age_seconds"], 180.0)
        self.assertGreaterEqual(heartbeat["heartbeat_age_seconds"], 599.0)

