        self.assertEqual(risk_preset_fix["errors"], [])
        self.assertEqual(risk_preset_fix["required_inputs"]["InpConsecutiveLossLimit"], ">= 20")
        self.assertIn("InpConsecutiveLossCooldownMinutes>=120", risk_preset_fix["command_text"])
        markdown = format_promotion_markdown({"next_actions": actions})
