    def test_promotion_checks_reject_mt5_forward_score_inversion(self):
        summary = {
            "overall": {"count": 120, "avg_r": 0.2, "pf": 1.4, "max_losing_streak": 4},
            "side": [
                {"group": "buy", "count": 60, "pf": 1.3},
                {"group": "sell", "count": 60, "pf": 1.2},
            ],
        }
        forward = {"closed": 30, "avg_r": 0.3, "pf": 1.5}
        mt5_forward = {
            "overall": {"closed": 35, "pf": 1.8, "max_losing_streak": 4},
            **mt5_forward_safe_risk_fixture(),
            "by_action": [
                {"group": "buy", "closed": 18, "pf": 1.4, "avg_price_r": 0.2},
                {"group": "sell", "closed": 17, "pf": 1.3, "avg_price_r": 0.1},
            ],
            "button": {"rows": 1, "dry_runs": 1, "ignored": 0, "unsafe": 0},
            "side_score_diagnostics": [
                {
                    "side": "buy",
                    "status": "candidate_gate",
                    "base_pf": 1.2,
                    "high_pf": 1.4,
                    "recommendation": "candidate gate: buy score >= 70",
                },
                {
                    "side": "sell",
                    "status": "score_inversion",
                    "base_pf": 1.4,
                    "high_pf": 0.9,
                    "recommendation": "refit side-specific scoring; avoid high-score gate for this side",
                },
            ],
        }

        checks = promotion_checks(
            history_hours=168,
            summary=summary,
            audit={"outcome": "skipped"},
            forward_summary=forward,
            mt5_forward_summary=mt5_forward,
            min_history_hours=168,
            min_candidates=100,
            min_avg_r=0.0,
            min_pf=1.2,
            max_losing_streak_allowed=8,
            min_side_count=30,
            min_side_pf=1.0,
            require_dry_run_passed=False,
            max_dry_run_age_seconds=3600,
            require_forward=True,
            min_forward_closed=30,
            min_forward_avg_r=0.0,
            min_forward_pf=1.2,
            require_mt5_forward=True,
            min_mt5_forward_closed=30,
            min_mt5_forward_pf=1.2,
            max_mt5_forward_losing_streak=7,
            min_mt5_forward_side_closed=10,
            min_mt5_forward_side_pf=1.0,
            min_mt5_forward_side_avg_price_r=0.0,
        )
        report = {"checks": checks, "mt5_forward_test": mt5_forward}
        actions = build_promotion_next_actions(report)

        self.assertTrue(next(item for item in checks if item["name"] == "mt5_forward_buy_score_not_inverted")["passed"])
        sell_score_check = next(item for item in checks if item["name"] == "mt5_forward_sell_score_not_inverted")
        self.assertFalse(sell_score_check["passed"])
        self.assertIn("score_inversion", str(sell_score_check["value"]))
        self.assertTrue(
            any(action["action"] == "refit_mt5_side_score_function_before_forward_promotion" for action in actions)
        )
        self.assertFalse(
            any(action["action"] == "rerun_forward_with_candidate_set_after_optimization" for action in actions)
        )
        score_action = next(
            action
            for action in actions
            if action["action"] == "refit_mt5_side_score_function_before_forward_promotion"
        )
        self.assertEqual(score_action["area"], "mt5_forward_score")
        self.assertIn("score_inversion", str(score_action["evidence"]["side_score_diagnostics"]))
        self.assertEqual(
            score_action["evidence"]["execution"]["config"],
            "methods/swing_eval/mt5/TesterConfigs/Swing_Evaluation_Trader_next_optimization.ini",
        )
        self.assertIn("--focus-side sell", score_action["evidence"]["execution"]["command_text"])
        self.assertIn("--side sell", score_action["evidence"]["score_weight_search"]["command_text"])
        self.assertIn("--regime-search", score_action["evidence"]["score_weight_search"]["command_text"])
        self.assertIn("runtime/latest_score_weight_search_168h_sell_rr4.json", score_action["evidence"]["score_weight_search"]["command_text"])
        self.assertIn("runtime/latest_score_weight_search_168h_sell_rr4.md", score_action["evidence"]["score_weight_search"]["command_text"])

