    def test_promotion_checks_reject_mt5_optimization_score_inversion(self):
        optimization = {
            "overall": {"closed": 500, "pf": 1.42, "net_profit": 1200.0},
            "by_action": [
                {"group": "buy", "closed": 230, "pf": 1.18, "avg_price_r": 0.05},
                {"group": "sell", "closed": 270, "pf": 1.55, "avg_price_r": 0.22},
            ],
            "side_score_diagnostics": [
                {
                    "side": "buy",
                    "status": "candidate_gate",
                    "base_pf": 1.1,
                    "high_pf": 1.3,
                    "recommendation": "candidate gate: buy score >= 70",
                },
                {
                    "side": "sell",
                    "status": "score_inversion",
                    "base_pf": 1.5,
                    "high_pf": 0.8,
                    "recommendation": "refit side-specific scoring; avoid high-score gate for this side",
                },
            ],
        }

        checks = promotion_checks(
            history_hours=168,
            summary=promotion_summary_fixture(),
            audit={"outcome": "skipped"},
            forward_summary={},
            mt5_optimization_summary=optimization,
            min_history_hours=168,
            min_candidates=100,
            min_avg_r=0.0,
            min_pf=1.2,
            max_losing_streak_allowed=8,
            min_side_count=30,
            min_side_pf=1.0,
            require_dry_run_passed=False,
            max_dry_run_age_seconds=3600,
            require_forward=False,
            min_forward_closed=30,
            min_forward_avg_r=0.0,
            min_forward_pf=1.2,
            require_mt5_optimization=False,
            min_mt5_optimization_closed=100,
            min_mt5_optimization_pf=1.2,
            min_mt5_optimization_side_closed=30,
            min_mt5_optimization_side_pf=1.0,
            min_mt5_optimization_side_avg_price_r=0.0,
            min_mt5_optimization_forward_pf=1.2,
            min_mt5_optimization_forward_trades=30,
            min_mt5_optimization_positive_forward_back=1,
        )
        report = {"checks": checks, "mt5_optimization": optimization}
        actions = build_promotion_next_actions(report)

        sell_score_check = next(item for item in checks if item["name"] == "mt5_optimization_sell_score_not_inverted")
        self.assertFalse(sell_score_check["passed"])
        action = next(
            item
            for item in actions
            if item["action"] == "refit_mt5_side_score_function_before_optimization_promotion"
        )
        self.assertEqual(action["area"], "mt5_optimization_score")
        self.assertIn("score_inversion", str(action["evidence"]["side_score_diagnostics"]))
        self.assertIn("--focus-side sell", action["evidence"]["execution"]["command_text"])
        self.assertIn("--side sell", action["evidence"]["score_weight_search"]["command_text"])
        markdown = format_promotion_markdown(report)
        self.assertIn("score_weight_search", markdown)
        self.assertIn("methods/swing_eval/analysis/weight_search.py --history runtime/latest_history_168h.json --rr 4 --side sell", markdown)

    def test_extract_mt5_optimization_summary_unwraps_nested_summary_payload(self):
        payload = {"ok": True, "summary": {"ok": True, "summary": {"overall": {"closed": 123, "pf": 1.23}}}}

        summary = extract_mt5_optimization_summary(payload)

        self.assertEqual(summary["overall"]["closed"], 123)
        self.assertEqual(summary["overall"]["pf"], 1.23)

