    def test_mt5_next_action_runner_blocks_mt5_execute_when_required_bridge_recovery_not_ready(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            gate_path = root / "promotion.json"
            bridge_plan = root / "bridge_recovery.json"
            output_json = root / "next_action.json"
            output_md = root / "next_action.md"
            gate_path.write_text(
                json.dumps(
                    {
                        "generated_at": "2026.07.13 07:43",
                        "decision": "not_ready",
                        "next_actions": [
                            {
                                "priority": 1,
                                "area": "score_weight_calibration",
                                "action": "collect_more_score_refit_samples",
                                "evidence": {
                                    "score_weight_sample_collection": {
                                        "kind": "score_weight_sample_collection",
                                        "focus_side": "sell",
                                        "config": "methods/swing_eval/mt5/TesterConfigs/Swing_Evaluation_Trader_sample_collection.ini",
                                        "set": "methods/swing_eval/mt5/TesterSets/Swing_Evaluation_Trader_sample_collection.set",
                                        "command": [
                                            "python3",
                                            "methods/swing_eval/analysis/mt5_tester_run.py",
                                            "--config",
                                            "methods/swing_eval/mt5/TesterConfigs/Swing_Evaluation_Trader_sample_collection.ini",
                                        ],
                                        "command_text": (
                                            "python3 methods/swing_eval/analysis/mt5_tester_run.py "
                                            "--config methods/swing_eval/mt5/TesterConfigs/Swing_Evaluation_Trader_sample_collection.ini"
                                        ),
                                    },
                                },
                            }
                        ],
                    }
                ),
                encoding="utf-8",
            )
            bridge_plan.write_text(
                json.dumps(
                    {
                        "ok": False,
                        "status": "needs_ea_restart",
                        "ready_for_mt5_validation": False,
                        "blocking_reasons": ["operational_status:ea_not_posting"],
                        "next_action": "restart_ai_bridge_advisor_and_wait_for_snapshot_post",
                    }
                ),
                encoding="utf-8",
            )

            with patch("analysis.mt5_next_action_run.subprocess.run") as run_mock:
                with redirect_stdout(io.StringIO()):
                    exit_code = mt5_next_action_run_main(
                        [
                            "--promotion-gate",
                            str(gate_path),
                            "--target",
                            "score_weight_sample_collection",
                            "--execute",
                            "--skip-ready-status-check",
                            "--bridge-recovery-plan",
                            str(bridge_plan),
                            "--require-bridge-ready",
                            "--output-json",
                            str(output_json),
                            "--output-md",
                            str(output_md),
                        ]
                    )
            payload = json.loads(output_json.read_text(encoding="utf-8"))
            markdown = output_md.read_text(encoding="utf-8")

        self.assertEqual(exit_code, 2)
        run_mock.assert_not_called()
        self.assertEqual(payload["blocked_before_primary"], "bridge_recovery_not_ready")
        self.assertTrue(payload["mt5_validation_blocked_by_bridge"])
        self.assertEqual(payload["bridge_recovery_plan"]["status"], "needs_ea_restart")
        self.assertEqual(payload["execution_hints"]["execute_command_text"], "")
        self.assertEqual(payload["execution_hints"]["collect_only_command_text"], "")
        self.assertFalse(payload["manual_strategy_tester"]["available"])
        self.assertIn("## Bridge Recovery", markdown)
        self.assertIn("MT5 execution: blocked until Bridge Recovery is ready.", markdown)
        self.assertNotIn("Execute with MT5 launch: python3 methods/swing_eval/analysis/mt5_next_action_run.py", markdown)
        self.assertNotIn("## Manual Strategy Tester Checklist", markdown)

