    def test_promotion_checks_reject_unsafe_mt5_button_rows(self):
        summary = {
            "overall": {"count": 120, "avg_r": 0.2, "pf": 1.4, "max_losing_streak": 4},
            "side": [
                {"group": "buy", "count": 60, "pf": 1.3},
                {"group": "sell", "count": 60, "pf": 1.2},
            ],
        }
        forward = {"closed": 30, "avg_r": 0.3, "pf": 1.5}
        mt5_forward = {
            "overall": {"closed": 35, "pf": 1.8, "max_losing_streak": 4},
            **mt5_forward_safe_risk_fixture(),
            "by_action": [
                {"group": "buy", "closed": 18, "pf": 1.4, "avg_price_r": 0.2},
                {"group": "sell", "closed": 17, "pf": 1.3, "avg_price_r": 0.1},
            ],
            "button": {"rows": 1, "dry_runs": 0, "ignored": 0, "unsafe": 1},
        }

        checks = promotion_checks(
            history_hours=168,
            summary=summary,
            audit={"outcome": "skipped"},
            forward_summary=forward,
            mt5_forward_summary=mt5_forward,
            min_history_hours=168,
            min_candidates=100,
            min_avg_r=0.0,
            min_pf=1.2,
            max_losing_streak_allowed=8,
            min_side_count=30,
            min_side_pf=1.0,
            require_dry_run_passed=False,
            max_dry_run_age_seconds=3600,
            require_forward=True,
            min_forward_closed=30,
            min_forward_avg_r=0.0,
            min_forward_pf=1.2,
            require_mt5_forward=True,
            min_mt5_forward_closed=30,
            min_mt5_forward_pf=1.2,
            max_mt5_forward_losing_streak=7,
        )

        self.assertFalse(next(item for item in checks if item["name"] == "mt5_forward_button_dry_run_only")["passed"])
        report = {
            "checks": checks,
            "summary": summary,
            "forward_test": forward,
            "mt5_forward_test": mt5_forward,
            "mt5_optimization": {},
            "mt5_optimization_recommendation": {},
            "mt5_tester_status": {},
            "mt5_back_forward_run": {},
            "mt5_compile_status": {},
            "winrate_fit": {},
        }
        actions = build_promotion_next_actions(report)
        by_area = {str(action["area"]): action for action in actions}

        self.assertIn("mt5_forward_button", by_area)
        action = by_area["mt5_forward_button"]
        self.assertEqual(action["action"], "disable_chart_button_trading_before_forward_promotion")
        self.assertIn("mt5_forward_button_dry_run_only", action["evidence"]["failed_checks"])
        self.assertEqual(action["evidence"]["button"]["unsafe"], 1)
        self.assertEqual(action["evidence"]["risk_preset_fix"]["kind"], "mt5_risk_preset_fix")
        self.assertEqual(
            action["evidence"]["risk_preset_fix"]["required_inputs"]["InpChartButtonDryRunOnly"],
            "true",
        )
        self.assertIn("methods/swing_eval/analysis/mt5_tester_run.py", action["evidence"]["execution"]["command_text"])

        markdown = format_promotion_markdown({**report, "next_actions": actions})
        self.assertIn("mt5_forward_button", markdown)
        self.assertIn("mt5_forward_button: rows=1, dry_run/ignored=0/0, unsafe=1", markdown)
        self.assertIn("InpChartButtonDryRunOnly=true", markdown)
        self.assertIn("InpAllowChartButtonTrading=false", markdown)

