    def test_promotion_checks_reject_mt5_optimization_source_time_mismatch(self):
        checks = mt5_optimization_source_time_checks(
            {
                "source_time_coverage": {
                    "close_rows_with_server_time": 12,
                    "close_rows_without_server_time": 0,
                },
                "source_time_diagnostics": {
                    "expected_from_date": "2025.01.01",
                    "expected_to_date": "2025.12.31",
                    "actual_first_server_time": "2026.07.07 00:05:00",
                    "actual_last_server_time": "2026.07.07 00:10:00",
                    "matches_expected_range": False,
                    "warnings": ["last close 2026.07.07 is after expected ToDate 2025.12.31"],
                },
            },
            prefix="mt5_optimization",
        )

        source_time_check = next(item for item in checks if item["name"] == "mt5_optimization_source_time_range")
        self.assertFalse(source_time_check["passed"])
        self.assertIn("expected ToDate", "; ".join(source_time_check["value"]["warnings"]))
        report = {
            "generated_at": "2026.07.09 05:34",
            "checks": checks,
            "mt5_optimization": {},
        }
        actions = build_promotion_next_actions(report)
        action = next(item for item in actions if item["area"] == "mt5_optimization_source_time")
        archive_preview = action["evidence"]["archive_preview"]
        execution = action["evidence"]["execution"]
        expected_run_id = "promotion_20260709_0534_mt5_optimization_source_time_next_optimization_both"
        self.assertEqual(archive_preview["run_id"], expected_run_id)
        self.assertTrue(archive_preview["include_source_time"])
        self.assertEqual(execution["agent_csv_archive_run_id"], expected_run_id)
        self.assertIn(f"--run-id {expected_run_id}", archive_preview["command_text"])
        self.assertIn("--include-source-time", archive_preview["command_text"])
        self.assertIn(f"--agent-csv-archive-run-id {expected_run_id}", execution["command_text"])

        markdown = format_promotion_markdown(report)
        self.assertIn(
            "source_time_gap: expected=2025.01.01..2025.12.31, actual=2026.07.07 00:05:00..2026.07.07 00:10:00, matches=False",
            markdown,
        )
        self.assertIn("with_server_time=12", markdown)
        self.assertIn("without_server_time=0", markdown)
        self.assertIn("source_time_warnings: last close 2026.07.07 is after expected ToDate 2025.12.31", markdown)

