    def test_promotion_checks_do_not_double_count_prelaunch_block_as_archive_or_report_failure(self):
        checks = promotion_checks(
            history_hours=168,
            summary=promotion_summary_fixture(),
            audit={},
            forward_summary={},
            min_history_hours=168,
            min_candidates=100,
            min_avg_r=0.0,
            min_pf=1.2,
            max_losing_streak_allowed=8,
            min_side_count=30,
            min_side_pf=1.0,
            require_dry_run_passed=False,
            max_dry_run_age_seconds=3600,
            require_forward=False,
            min_forward_closed=30,
            min_forward_avg_r=0.0,
            min_forward_pf=1.2,
            mt5_tester_run_summary={
                "generated_at": "2026.07.09 06:45",
                "ok": False,
                "blocked": True,
                "collect_only": False,
                "dry_run": False,
                "archive_agent_csvs_before_run": False,
                "agent_csv_archive_required": True,
                "agent_csv_archive_missing": True,
                "source_time_blocked": False,
                "terminal_failed": False,
                "report_fallback_blocked": False,
                "terminal_run": None,
                "report_paths": {"source": "blocked_not_collected"},
                "blocked_components": {
                    "compile_stale": False,
                    "risk_preset_invalid": True,
                    "agent_csv_archive_failed": False,
                },
                "compile_blocked": False,
                "risk_preset_blocked": True,
                "agent_csv_archive_blocked": False,
                "risk_preset": {
                    "set_file": "methods/swing_eval/mt5/TesterSets/old_forward.set",
                    "mode": "forward_or_optimization",
                    "ok": False,
                    "inputs": {"InpConsecutiveLossLimit": "3"},
                    "errors": ["InpConsecutiveLossLimit 3 < expected 20"],
                },
                "warnings": ["tester risk preset is invalid; rerun blocked before MT5 launch"],
            },
        )

        by_name = {item["name"]: item for item in checks}
        self.assertFalse(by_name["mt5_tester_run_ok"]["passed"])
        self.assertEqual(
            by_name["mt5_tester_run_ok"]["value"]["blocked_components"],
            {"compile_stale": False, "risk_preset_invalid": True, "agent_csv_archive_failed": False},
        )
        self.assertTrue(by_name["mt5_tester_run_ok"]["value"]["risk_preset_blocked"])
        self.assertEqual(
            by_name["mt5_tester_run_ok"]["value"]["risk_preset"]["errors"],
            ["InpConsecutiveLossLimit 3 < expected 20"],
        )
        self.assertTrue(by_name["mt5_tester_run_agent_csv_archive"]["passed"])
        self.assertTrue(by_name["mt5_tester_run_report_paths"]["passed"])
        self.assertTrue(by_name["mt5_tester_run_terminal"]["passed"])

        actions = build_promotion_next_actions(
            {
                "generated_at": "2026.07.09 06:46",
                "checks": checks,
                "mt5_optimization": {},
            }
        )
        action = next(item for item in actions if item["area"] == "mt5_tester_run")
        self.assertIn("methods/swing_eval/analysis/mt5_compile.py", action["evidence"]["compile"]["command_text"])
        self.assertEqual(action["evidence"]["risk_preset_fix"]["set_file"], "methods/swing_eval/mt5/TesterSets/old_forward.set")
        self.assertEqual(
            action["evidence"]["risk_preset_fix"]["required_inputs"]["InpConsecutiveLossLimit"],
            ">= 20",
        )
        markdown = format_promotion_markdown({"generated_at": "2026.07.09 06:46", "next_actions": actions})
        self.assertIn("mt5_tester_run risk_preset_fix", markdown)
        self.assertIn("current_inputs: InpConsecutiveLossLimit=3", markdown)
        self.assertIn("errors: InpConsecutiveLossLimit 3 < expected 20", markdown)
        self.assertIn("InpConsecutiveLossCooldownMinutes >= 120", markdown)
        self.assertIn("manual: fix MT5 risk preset in methods/swing_eval/mt5/TesterSets/old_forward.set", markdown)

