    def test_promotion_next_actions_defer_chronological_reject_after_completed_sell_refit_score_sample(self):
        optimization = {
            "overall": {"closed": 500, "pf": 1.42, "net_profit": 1200.0},
            "chronological_splits": [
                {
                    "group": "q1",
                    "closed": 250,
                    "pf": 1.45,
                    "avg_price_r": 0.18,
                    "net_profit": 520.0,
                },
                {
                    "group": "q2",
                    "closed": 250,
                    "pf": 0.86,
                    "avg_price_r": -0.1,
                    "net_profit": -90.0,
                    "diagnosis": "chronological split failed: q2",
                },
            ],
            "weak_time_segments": [
                {"group": "sell 03:00-04:00", "closed": 80, "pf": 0.7, "avg_price_r": -0.2}
            ],
            "weak_trend_segments": [
                {"group": "sell M30 up M15 up", "closed": 90, "pf": 0.8, "avg_price_r": -0.1}
            ],
            "weak_segments": [
                {"group": "sell RR 3.00 TP 800-900pt", "closed": 75, "pf": 0.75, "avg_price_r": -0.12}
            ],
        }
        report = {
            "generated_at": "2026.07.13 15:31",
            "checks": [
                {
                    "name": "mt5_optimization_chronological_splits",
                    "passed": False,
                    "value": [{"group": "q2", "pf": 0.86, "avg_price_r": -0.1}],
                    "requirement": "failed chronological splits = 0",
                },
            ],
            "mt5_optimization": optimization,
            "mt5_optimization_recommendation": {
                "decision": {
                    "adoptable": False,
                    "reasons": ["chronological split failed: q2 PF 0.86"],
                },
                "set_metadata": {
                    "focus_side": "sell",
                    "skipped_write": True,
                    "skip_reason": "not_adoptable",
                },
            },
            "mt5_sell_regime_entry_refit_recommendation": {
                "decision": {
                    "adoptable": False,
                    "overall_closed": 640,
                    "reasons": ["sell score refit required"],
                },
                "side_status": {
                    "sell": {
                        "status": "score_refit_required",
                        "closed": 640,
                        "pf": 1.08,
                        "avg_price_r": 0.04,
                    }
                },
                "set_metadata": {
                    "focus_side": "sell",
                    "skipped_write": True,
                    "skip_reason": "score_refit_required",
                },
            },
            "score_weight_set_by_side": {
                "sell": {
                    "focus_side": "sell",
                    "written": False,
                    "skipped_write": True,
                    "skip_reason": "walk_forward_sample_shortage",
                    "walk_forward_status": "walk_forward_sample_shortage",
                    "output_set": "methods/swing_eval/mt5/TesterSets/Swing_Evaluation_Trader_sell_score_weight_refit.set",
                }
            },
        }

        actions = build_promotion_next_actions(report)
        by_area = {str(action["area"]): action for action in actions}

        self.assertNotIn(
            "reject_chronologically_unstable_optimization",
            {str(action["action"]) for action in actions},
        )
        self.assertEqual(
            by_area["sell_score_refit"]["action"],
            "refit_sell_score_function_after_regime_entry_refit",
        )
        evidence = by_area["sell_score_refit"]["evidence"]
        self.assertIn("score_weight_sample_collection", evidence)
        self.assertEqual(
            evidence["upstream_chronological_rejection"]["failed_splits"][0]["group"],
            "q2",
        )
        self.assertEqual(
            evidence["upstream_chronological_rejection"]["weak_time_segments"][0]["group"],
            "sell 03:00-04:00",
        )
        plan = select_next_action_plan(
            {"generated_at": "2026.07.13 15:31", "decision": "not_ready", "next_actions": actions}
        )
        self.assertEqual(plan["target"], "score_weight_sample_collection")
        self.assertIn("upstream_chronological_rejection", plan["action_context"])

