    def test_performance_comparison_rows_show_forward_drift_from_backtest(self):
        rows = performance_comparison_rows(
            summary={
                "overall": {
                    "count": 120,
                    "pf": 1.5,
                    "avg_r": 0.3,
                    "expectancy_r": 0.3,
                    "max_drawdown_r": 8.0,
                }
            },
            forward_summary={
                "closed": 30,
                "pf": 1.1,
                "avg_r": 0.05,
                "expectancy_r": 0.05,
                "max_drawdown_r": 12.0,
            },
            mt5_forward_summary={
                "overall": {
                    "closed": 40,
                    "pf": 0.9,
                    "avg_price_r": -0.02,
                    "expectancy_price_r": -0.02,
                    "max_drawdown_price_r": 18.0,
                }
            },
            mt5_optimization_summary={},
            mt5_yearly_optimization_summary={},
        )

        by_dataset = {row["dataset"]: row for row in rows}
        self.assertEqual(by_dataset["backtest"]["pf_delta_vs_backtest"], 0.0)
        self.assertEqual(by_dataset["python_forward"]["pf_delta_vs_backtest"], -0.4)
