    def test_promotion_archive_run_id_uses_stable_input_artifact_time(self):
        first = {
            "generated_at": "2026.07.13 19:15",
            "mt5_tester_status": {"generated_at": "2026.07.13 19:15"},
            "mt5_back_forward_run": {"generated_at": "2026.07.13 19:14"},
            "score_weight_set_by_side": {
                "sell": {
                    "generated_at": "2026.07.13 17:12",
                    "skip_reason": "walk_forward_not_passed",
                }
            },
        }
        second = {
            **first,
            "generated_at": "2026.07.13 19:17",
            "mt5_tester_status": {"generated_at": "2026.07.13 19:17"},
            "mt5_back_forward_run": {"generated_at": "2026.07.13 19:17"},
        }
        changed_input = {
            **second,
            "score_weight_set_by_side": {
                "sell": {
                    "generated_at": "2026.07.13 17:18",
                    "skip_reason": "walk_forward_not_passed",
                }
            },
        }

        self.assertEqual(
            promotion_archive_run_id(first, "score_weight_sample_collection", "sample_collection", "sell"),
            "promotion_20260713_1712_score_weight_sample_collection_sample_collection_sell",
        )
        self.assertEqual(
            promotion_archive_run_id(first, "score_weight_sample_collection", "sample_collection", "sell"),
            promotion_archive_run_id(second, "score_weight_sample_collection", "sample_collection", "sell"),
        )
        for area, kind, focus_side in (
            ("mt5_forward", "strategy_forward", "both"),
            ("mt5_yearly_validation", "next_optimization_2025", "both"),
            ("mt5_tester", "next_optimization", "both"),
            ("mt5_tester_run_ok", "next_optimization", "both"),
        ):
            self.assertEqual(
                promotion_archive_run_id(first, area, kind, focus_side),
                promotion_archive_run_id(second, area, kind, focus_side),
            )
        self.assertEqual(
            promotion_archive_run_id(changed_input, "score_weight_sample_collection", "sample_collection", "sell"),
            "promotion_20260713_1718_score_weight_sample_collection_sample_collection_sell",
        )

