    def test_promotion_checks_reject_mt5_status_watcher_back_forward_mismatch(self):
        status = extract_mt5_tester_status_summary(
            {
                "generated_at": "2026.07.13 08:22",
                "operational_status": "latest_run_ok",
                "ready_for_tester_launch": True,
                "status_watch_heartbeat": {
                    "status": "ok",
                    "fresh": True,
                    "compatible": True,
                    "missing_required_fields": [],
                    "implementation_version": STATUS_WATCH_HEARTBEAT_IMPLEMENTATION_VERSION,
                    "expected_implementation_version": STATUS_WATCH_HEARTBEAT_IMPLEMENTATION_VERSION,
                    "implementation_version_mismatch": False,
                    "watcher_pid": 30162,
                    "back_forward_run_execution_conditions": {
                        "per_step_timeout_seconds": 3600,
                        "since_minutes": 240.0,
                        "min_closed": 30,
                        "from_date": "",
                        "to_date": "",
                        "forward_mode": "3",
                    },
                    "back_forward_run_forward_mode": "3",
                    "back_forward_run_effective_from_date": "",
                    "back_forward_run_effective_to_date": "",
                    "back_forward_run_effective_forward_mode": "0,3",
                },
            }
        )
        runner = extract_mt5_back_forward_run_summary(
            {
                "ok": True,
                "generated_at": "2026.07.13 08:21",
                "mode": "both",
                "execute": False,
                "dry_run": True,
                "execution_conditions": {
                    "per_step_timeout_seconds": 3600,
                    "since_minutes": 240.0,
                    "min_closed": 30,
                    "from_date": "",
                    "to_date": "",
                    "forward_mode": "",
                },
                "steps": [{"label": "backtest"}, {"label": "forward"}],
            }
        )
        checks = promotion_checks(
            history_hours=168,
            summary={
                "overall": {"count": 120, "avg_r": 0.2, "pf": 1.4, "max_losing_streak": 4},
                "side": [
                    {"group": "buy", "count": 60, "pf": 1.3},
                    {"group": "sell", "count": 60, "pf": 1.2},
                ],
            },
            audit={},
            forward_summary={},
            mt5_tester_status_summary=status,
            mt5_back_forward_run_summary=runner,
            min_history_hours=168,
            min_candidates=100,
            min_avg_r=0.0,
            min_pf=1.2,
            max_losing_streak_allowed=8,
            min_side_count=30,
            min_side_pf=1.0,
            require_dry_run_passed=False,
            max_dry_run_age_seconds=3600,
            require_forward=False,
            min_forward_closed=30,
            min_forward_avg_r=0.0,
            min_forward_pf=1.2,
        )

        by_name = {row["name"]: row for row in checks}
        self.assertTrue(by_name["mt5_status_watch_heartbeat"]["passed"])
        self.assertFalse(by_name["mt5_status_watch_back_forward_current"]["passed"])
        self.assertEqual(
            by_name["mt5_status_watch_back_forward_current"]["value"]["mismatches"],
            ["forward_mode:3->"],
        )

        report = {
            "checks": checks,
            "summary": {},
            "forward_test": {},
            "mt5_forward_test": {},
            "mt5_optimization": {},
            "mt5_optimization_recommendation": {},
            "mt5_tester_status": status,
            "mt5_back_forward_run": runner,
            "mt5_compile_status": {},
            "winrate_fit": {},
        }
        actions = build_promotion_next_actions(report)
        action = next(item for item in actions if item["area"] == "mt5_status_watch")

        self.assertIn("mt5_status_watch_back_forward_current", action["evidence"]["failed_checks"])
        markdown = format_promotion_markdown({**report, "next_actions": actions})
        self.assertIn("mt5_status_watch_back_forward_current: mismatches=forward_mode:3->", markdown)
        self.assertIn("watcher_forward_mode=3", markdown)
        self.assertIn("expected_forward_mode=", markdown)

