    def test_mt5_strategy_tester_analysis_reports_buy_candidate_gap_plan(self):
        reports = [
            {
                "label": "sell_hour12_m30m15_2025",
                "side": "SELL",
                "window": "annual",
                "status": "candidate",
                "metrics": {"closed": 39315, "pf": 1.3786, "avg_price_r": 0.2914},
                "tester_xml": {"stable_forward_positive_back_positive": 30},
            },
            {
                "label": "buy_wide_stop_short",
                "side": "BUY",
                "window": "short",
                "status": "aggregate_only",
                "metrics": {"closed": 7267, "pf": 1.4914, "avg_price_r": 0.3299},
                "tester_xml": {"stable_forward_positive_back_positive": 0},
                "source_time": {"status": "source_files_stale"},
                "source_files": {"status": "stale"},
            },
            {
                "label": "buy_hour03_wide_stop_2025",
                "side": "BUY",
                "window": "annual",
                "status": "below_promotion_threshold",
                "metrics": {"closed": 60491, "pf": 1.1593, "avg_price_r": 0.1157},
                "tester_xml": {"stable_forward_positive_back_positive": 0},
                "source_time": {"status": "source_files_stale"},
                "source_files": {
                    "status": "stale",
                    "checked": 14,
                    "stale": 3,
                    "missing": 1,
                    "archived": 10,
                    "examples": [
                        {
                            "path": "runtime/agent-current.csv",
                            "reason": "mtime 2026.07.08 22:20->2026.07.18 09:30",
                        }
                    ],
                },
            },
        ]
        manual_queue = {
            "operation_cards": [
                {
                    "queue_id": "static_buy_wide_stop_short",
                    "step_label": "buy_wide_stop_short",
                    "dates": "2026.06.30 -> 2026.07.08",
                    "forward": "1/4",
                    "inputs": "Swing_Evaluation_Trader_buy_wide_stop_validation.set",
                    "report": "Tester\\Swing_Evaluation_Trader_buy_wide_stop_validation",
                }
            ],
            "execution_checklist": [
                {
                    "queue_id": "static_buy_wide_stop_short",
                    "step_label": "buy_wide_stop_short",
                    "launch_command_kind": "runner_execute",
                }
            ],
        }

        plan = build_buy_candidate_gap_plan(reports, manual_queue)
        markdown = format_mt5_strategy_tester_analysis_markdown(
            {
                "generated_at": "2026.07.17 03:10",
                "promotion_gate": {"decision": "not_ready"},
                "spec_coverage": {"not_complete_reasons": []},
                "back_forward_run": {},
                "tester_status": {},
                "manual_test_queue": {},
                "manual_test_queue_with_optimization": manual_queue,
                "source_artifacts": [],
                "optimization_reports": reports,
                "source_time_refresh_plan": {"status": "ok", "entries": []},
                "buy_candidate_gap_plan": plan,
                "adoption": {
                    "status": "not_ready",
                    "candidate_labels": ["sell_hour12_m30m15_2025"],
                    "aggregate_only_labels": ["buy_wide_stop_short"],
                    "blockers": ["buy_candidate_missing"],
                },
            }
        )

        self.assertEqual(plan["status"], "needs_buy_diagnostic")
        self.assertEqual(
            plan["diagnostic_labels"],
            ["buy_wide_stop_short", "buy_hour03_wide_stop_2025"],
        )
        self.assertIn("--include-static-candidate-label buy_wide_stop_short", plan["refresh_queue_command_text"])
        self.assertIn("--include-static-candidate-label buy_hour03_wide_stop_2025", plan["refresh_queue_command_text"])
        self.assertIn("--include-static-candidate-label sell_hour12_m30m15_2025", plan["refresh_queue_command_text"])
        self.assertTrue(plan["entries"][0]["manual_queue_matched"])
        self.assertFalse(plan["entries"][1]["manual_queue_matched"])
        hour03_entry = next(
            entry
            for entry in plan["entries"]
            if entry["label"] == "buy_hour03_wide_stop_2025"
        )
        self.assertEqual(hour03_entry["source_file_checked"], 14)
        self.assertEqual(hour03_entry["source_file_stale"], 3)
        self.assertEqual(hour03_entry["source_file_missing"], 1)
        self.assertEqual(hour03_entry["source_file_archived"], 10)
        self.assertEqual(
            hour03_entry["source_file_examples"][0]["path"],
            "runtime/agent-current.csv",
        )
        self.assertIn("## BUY Candidate Gap Plan", markdown)
        self.assertIn("BUY candidate is missing", markdown)
        self.assertIn("buy_wide_stop_short", markdown)
        self.assertIn("source_files_stale", markdown)
        self.assertIn("stale, 14/3/1", markdown)
        self.assertIn("Tester\\Swing_Evaluation_Trader_buy_wide_stop_validation", markdown)

