        self.assertEqual(payload["back_forward_evidence_state"], "plan_only")
        self.assertEqual(payload["back_forward_performance_status"], "missing_backtest_or_forward_report")
        self.assertFalse(payload["manual_collect_ready"])
        self.assertEqual(payload["manual_collect_status"], "waiting_for_reports")
        self.assertEqual(payload["back_forward_decision_status"], "run_manual_back_forward")
        self.assertFalse(payload["back_forward_decision_adoptable"])
        self.assertEqual(
            payload["back_forward_decision_next_action"],
            "run_backtest_then_forward_in_mt5_strategy_tester",
        )
        self.assertIn("--collect-only", payload["back_forward_decision_collect_command_text"])
        self.assertEqual(payload["source_time_refresh_status"], "ok")
        self.assertEqual(payload["buy_candidate_gap_status"], "no_buy_diagnostic_available")
        self.assertIn("## Operator Decision", markdown)
        self.assertIn("Verdict: RUN_BACK_FORWARD", markdown)
        self.assertIn("Primary blocker: mt5_back_forward_not_executed", markdown)
        self.assertIn("Not adoptable yet: run Backtest and Forward", markdown)

