    def test_promotion_markdown_includes_optimization_recommendation_reasons(self):
        report = {
            "decision": "not_ready",
            "live_ready": False,
            "generated_at": "2026.07.09 00:00:00",
            "checks": [],
            "summary": {},
            "forward_test": {},
            "mt5_forward_test": {},
            "mt5_optimization": {},
            "mt5_optimization_recommendation": {
                "decision": {
                    "adoptable": False,
                    "reasons": [
                        "overall PF 1.121 < 1.2",
                        "top forward pass is positive forward but negative back",
                    ],
                },
                "set_metadata": {
                    "path": "methods/swing_eval/mt5/TesterSets/Swing_Evaluation_Trader_next_optimization.set",
                    "focus_side": "both",
                    "diagnostic_only": True,
                    "skipped_write": True,
                    "skip_reason": "diagnostic_only",
                    "optimized_input_count": 0,
                    "estimated_full_factorial_passes": 1,
                    "score_refit_sides": ["buy"],
                    "stable_hint_artifact_exclusions": [
                        {"parameter": "InpMinScore", "value": 55, "reason": "back-fit artifact"},
                        {"parameter": "InpUseFittedSellFilter", "value": False, "reason": "back-fit artifact"},
                    ],
                    "stable_hint_coverage": [
                        {"parameter": "InpMinScore", "applied": True, "requested_values": [55, 60]},
                        {
                            "parameter": "InpUseFittedSellFilter",
                            "applied": False,
                            "requested_values": [False],
                            "skip_reason": "all_values_excluded_as_back_fit_artifacts",
                        },
                    ],
                },
            },
            "mt5_compile_status": {},
            "winrate_fit": {},
            "next_actions": [],
        }

        markdown = format_promotion_markdown(report)

        self.assertIn("Recommendation decision: not_ready", markdown)
        self.assertIn("Recommendation reasons: overall PF 1.121 < 1.2; top forward pass is positive forward but negative back", markdown)
        self.assertIn("Next set score refit sides: buy", markdown)
        self.assertIn(
            "Next set stable hint coverage: applied=1, skipped=1, "
            "skip_reasons=all_values_excluded_as_back_fit_artifacts:1, "
            "parameters=InpMinScore, InpUseFittedSellFilter",
            markdown,
        )
        self.assertIn("Stable hint artifact exclusions: InpMinScore=55, InpUseFittedSellFilter=False", markdown)

