        by_entry_hour = {row["group"]: row for row in summary["by_entry_server_hour"]}
        by_m30 = {row["group"]: row for row in summary["by_m30_trend"]}
        by_m15 = {row["group"]: row for row in summary["by_m15_trend"]}
        by_m5 = {row["group"]: row for row in summary["by_m5_trend"]}
        by_m30_slope = {row["group"]: row for row in summary["by_m30_slope"]}
        by_m15_slope = {row["group"]: row for row in summary["by_m15_slope"]}
        by_m30_m15 = {row["group"]: row for row in summary["by_m30_m15_trend"]}
        by_alignment = {row["group"]: row for row in summary["by_trend_alignment"]}
        by_action_alignment = {row["group"]: row for row in summary["by_action_trend_alignment"]}
        by_action_m30_m15 = {row["group"]: row for row in summary["by_action_m30_m15_trend"]}
        self.assertEqual(by_entry_hour["12:00-13:00"]["closed"], 2)
