        self.assertEqual(by_action_m30_m15["sell M30 down M15 down"]["closed"], 2)
        all_50 = next(row for row in summary["score_thresholds"] if row["side"] == "all" and row["threshold"] == 50)
        buy_50 = next(row for row in summary["score_thresholds"] if row["side"] == "buy" and row["threshold"] == 50)
