    def test_mt5_forward_report_diagnoses_side_score_inversion(self):
        rows = [
            {"event": "close", "action": "buy", "score": "50", "net_profit": "-100", "server_time": "2026.07.07 00:00:00"},
            {"event": "close", "action": "buy", "score": "100", "net_profit": "500", "server_time": "2026.07.07 00:01:00"},
            {"event": "close", "action": "sell", "score": "50", "net_profit": "100", "server_time": "2026.07.07 00:02:00"},
            {"event": "close", "action": "sell", "score": "100", "net_profit": "-300", "server_time": "2026.07.07 00:03:00"},
        ]

        summary = summarize_mt5_forward(rows, min_closed=1)
        diagnostics = {row["side"]: row for row in summary["side_score_diagnostics"]}
        markdown = format_markdown(summary)

        self.assertEqual(diagnostics["buy"]["status"], "candidate_gate")
        self.assertGreater(diagnostics["buy"]["pf_delta_best_vs_base"], 0)
        self.assertEqual(diagnostics["sell"]["status"], "score_inversion")
        self.assertIn("Side Score Diagnostics", markdown)
        self.assertIn("score_inversion", markdown)

