    def test_mt5_forward_report_main_prints_compact_summary_by_default(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            csv_path = Path(tmpdir) / "swing_evaluation_trades.csv"
            output_json = Path(tmpdir) / "latest_mt5_forward_report.json"
            output_md = Path(tmpdir) / "latest_mt5_forward_report.md"
            csv_path.write_text(
                "event,server_time,action,entry,sl,tp,risk_reward,score,stop_points,deal_price,net_profit\n"
                "close,2026.07.07 00:05:00,buy,100,99,102,2,55,100,102,200\n",
                encoding="utf-8",
            )

            stdout = io.StringIO()
            with redirect_stdout(stdout):
                code = mt5_forward_report_main(
                    [
                        "--input",
                        str(csv_path),
                        "--min-closed",
                        "1",
                        "--min-pf",
                        "1.0",
                        "--output-json",
                        str(output_json),
                        "--output-md",
                        str(output_md),
                    ]
                )
            payload = json.loads(stdout.getvalue())
            report_payload = json.loads(output_json.read_text(encoding="utf-8"))

        self.assertEqual(code, 0)
        self.assertNotIn("summary", payload)
        self.assertEqual(payload["output_json"], str(output_json))
        self.assertEqual(payload["output_md"], str(output_md))
        self.assertEqual(payload["closed"], 1)
        self.assertEqual(payload["pf"], 99.0)
        self.assertEqual(payload["failed_checks"], [])
        self.assertIn("summary", report_payload)
        self.assertEqual(report_payload["summary"]["overall"]["closed"], 1)

    def test_mt5_forward_collect_copies_latest_csv_and_writes_report(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir) / "Tester"
            old_dir = root / "Agent-1" / "MQL5" / "Files"
            new_dir = root / "Agent-2" / "MQL5" / "Files"
            old_dir.mkdir(parents=True)
            new_dir.mkdir(parents=True)
            old_path = old_dir / "swing_evaluation_trades.csv"
            new_path = new_dir / "swing_evaluation_trades.csv"
            old_path.write_text("event,server_time,action,net_profit\nclose,2026.07.07 00:00,buy,-50\n", encoding="utf-8")
            new_path.write_text("event,server_time,action,net_profit\nclose,2026.07.07 00:01,sell,120\n", encoding="utf-8")
            old_mtime = datetime(2026, 7, 7, 0, 0).timestamp()
            new_mtime = datetime(2026, 7, 7, 0, 1).timestamp()
            old_path.touch()
            new_path.touch()

            os.utime(old_path, (old_mtime, old_mtime))
            os.utime(new_path, (new_mtime, new_mtime))

            destination = Path(tmpdir) / "runtime" / "mt5_forward" / "swing_evaluation_trades.csv"
            output_json = Path(tmpdir) / "runtime" / "latest_mt5_forward_report.json"
            output_md = Path(tmpdir) / "runtime" / "latest_mt5_forward_report.md"
            status_json = Path(tmpdir) / "runtime" / "latest_mt5_forward_collect.json"
            status = collect_latest_mt5_forward(
                source_roots=[root],
                destination=destination,
                output_json=output_json,
                output_md=output_md,
                collect_status_json=status_json,
                min_closed=1,
            )

            self.assertTrue(status["ok"])
            self.assertEqual(status["selected"], str(new_path))
            self.assertEqual(status["summary"]["closed"], 1)
            self.assertTrue(destination.exists())
            self.assertIn("120", destination.read_text(encoding="utf-8"))
            self.assertTrue(output_json.exists())
            self.assertTrue(output_md.exists())
            self.assertTrue(status_json.exists())
            report_payload = json.loads(output_json.read_text(encoding="utf-8"))
            self.assertEqual(report_payload["rows_count"], 1)
            self.assertNotIn("rows", report_payload)
            self.assertEqual(len(report_payload["rows_sample"]), 1)

