    def test_mt5_tester_optimization_report_merges_agent_csvs(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir) / "Tester"
            first_dir = root / "Agent-127.0.0.1-3000" / "MQL5" / "Files"
            second_dir = root / "Agent-127.0.0.1-3001" / "MQL5" / "Files"
            first_dir.mkdir(parents=True)
            second_dir.mkdir(parents=True)
            header = (
                "event,server_time,opened_at,entry_server_hour,action,entry,sl,tp,risk_reward,score,stop_points,"
                "deal_price,net_profit,m30_trend,m15_trend,m5_trend,m30_slope,m15_slope,trend_alignment\n"
            )
            first = first_dir / "swing_evaluation_trades.csv"
            first.write_text(
                header
                + "open,2026.07.07 00:00:00,,,buy,100,99,102,2,55,100,100,0,up,up,up,rising,rising,all_up\n"
                + "close,2026.07.07 00:05:00,2026.07.07 00:00:00,00:00-01:00,buy,100,99,102,2,55,100,102,200,up,up,up,rising,rising,all_up\n"
                + "close,2026.07.07 00:10:00,2026.07.07 00:00:00,00:00-01:00,buy,100,99,102,2,85,100,99,-100,up,up,up,rising,rising,all_up\n",
                encoding="utf-8",
            )
            second = second_dir / "swing_evaluation_trades.csv"
            second.write_text(
                header
                + "close,2026.07.07 00:05:00,2026.07.07 12:01:00,12:00-13:00,sell,100,101,95,5,50,100,101,-100,down,down,down,falling,falling,all_down\n"
                + "close,2026.07.07 00:10:00,2026.07.07 12:01:00,12:00-13:00,sell,100,101,95,5,100,100,101,-100,down,down,down,falling,falling,all_down\n",
                encoding="utf-8",
            )

            paths = discover_tester_csvs([root], since_minutes=0)
            summary = summarize_optimization_csvs(
                paths,
                min_closed=1,
                weak_pf=1.0,
                expected_from_date="2026.07.07",
                expected_to_date="2026.07.07",
            )
            mismatch_summary = summarize_optimization_csvs(
                paths,
                min_closed=1,
                weak_pf=1.0,
                expected_from_date="2025.01.01",
                expected_to_date="2025.12.31",
            )
            summary["tester_xml"] = {"back": {"rows": 7}, "forward": {"rows": 3}}
            set_file = Path(tmpdir) / "run.set"
            set_file.write_text(
                "\n".join(
                    [
                        "InpMinScore=60||50||5||60||Y",
                        "InpUseFittedSellFilter=true||false||0||true||Y",
                    ]
                ),
                encoding="utf-8",
            )
            attach_set_pass_budget(summary, set_file)
            markdown = format_optimization_markdown(summary)

        by_rr = {row["group"]: row for row in summary["by_risk_reward"]}
        by_sl = {row["group"]: row for row in summary["by_stop_points"]}
        by_tp = {row["group"]: row for row in summary["by_take_profit_points"]}
        by_rr_sl = {row["group"]: row for row in summary["by_risk_reward_stop_points"]}
        by_rr_tp = {row["group"]: row for row in summary["by_risk_reward_take_profit_points"]}
        by_month = {row["group"]: row for row in summary["by_month"]}
        by_hour = {row["group"]: row for row in summary["by_server_hour"]}
        by_entry_hour = {row["group"]: row for row in summary["by_entry_server_hour"]}
        by_rr_month = {row["group"]: row for row in summary["by_action_risk_reward_month"]}
        by_m5 = {row["group"]: row for row in summary["by_m5_trend"]}
        by_m30_slope = {row["group"]: row for row in summary["by_m30_slope"]}
        by_m15_slope = {row["group"]: row for row in summary["by_m15_slope"]}
        by_alignment = {row["group"]: row for row in summary["by_trend_alignment"]}
        by_action_alignment = {row["group"]: row for row in summary["by_action_trend_alignment"]}
        chronological = {row["group"]: row for row in summary["chronological_splits"]}
        weak = {row["group"]: row for row in summary["weak_segments"]}
        weak_time = {row["group"]: row for row in summary["weak_time_segments"]}
        weak_trend = {row["group"]: row for row in summary["weak_trend_segments"]}
        score_all_50 = next(row for row in summary["score_thresholds"] if row["side"] == "all" and row["threshold"] == 50)
        score_buy_80 = next(row for row in summary["score_thresholds"] if row["side"] == "buy" and row["threshold"] == 80)
        side_score = {row["side"]: row for row in summary["side_score_diagnostics"]}

        self.assertEqual(len(paths), 2)
