    def test_mt5_optimization_recommendation_generates_side_focused_set(self):
        recommendation = {
            "decision": {"adoptable": False},
            "next_search": {
                "buy": {"primary_segments": [], "reference_segments": [], "rr_values": [], "sl_bands": []},
                "sell": {
                    "primary_segments": [
                        {"group": "sell RR 2.00 SL 250-300pt", "closed": 1000, "pf": 1.3},
                        {"group": "sell RR 4.00 SL 250-300pt", "closed": 800, "pf": 1.25},
                    ],
                    "reference_segments": [],
                    "rr_values": [2.0, 3.0, 4.0],
                    "sl_bands": ["250-300pt"],
                    "tp_bands": ["700-800pt"],
                },
            },
        }
        template = "\n".join(
            [
                "; template",
                "InpEnableBuy=true||false||0||true||N",
                "InpEnableSell=true||false||0||true||N",
                "InpUseSideRiskReward=true||false||0||true||N",
                "InpUseVariableRiskReward=true||false||0||true||N",
                "InpRiskReward=4.0||2.0||1.0||5.0||N",
                "InpBuyRiskReward=4.0||2.0||1.0||5.0||Y",
                "InpSellRiskReward=5.0||2.0||1.0||5.0||Y",
                "InpMinRiskReward=2.0||2.0||1.0||5.0||N",
                "InpMaxRiskReward=5.0||3.0||1.0||5.0||N",
                "InpMinStopPoints=25||25||5||80||N",
                "InpMaxStopPoints=300||300||25||500||N",
            ]
        )

        rendered, metadata = generate_next_optimization_set(template, recommendation, focus_side="auto")

        self.assertEqual(metadata["focus_side"], "sell")
        self.assertIn("InpEnableBuy=false||false||0||true||N", rendered)
        self.assertIn("InpEnableSell=true||false||0||true||N", rendered)
        self.assertIn("InpBuyRiskReward=4||4||1||4||N", rendered)
        self.assertIn("InpSellRiskReward=4||2||1||4||Y", rendered)
        self.assertIn("InpMinRiskReward=2||2||1||2||N", rendered)
