    def test_mt5_optimization_recommendation_cli_persists_skipped_set_metadata(self):
        summary = {
            "overall": {"closed": 1000, "pf": 1.1},
            "by_action": [
                {"group": "buy", "closed": 1000, "pf": 1.1, "avg_price_r": 0.04, "net_profit": 40.0},
            ],
            "best_segments": [
                {
                    "dimension": "by_risk_reward_stop_points",
                    "group": "buy RR 2.00 SL 250-300pt",
                    "closed": 700,
                    "pf": 1.25,
                    "avg_price_r": 0.12,
                    "net_profit": 70.0,
                }
            ],
            "weak_segments": [],
            "side_score_diagnostics": [
                {
                    "side": "buy",
                    "status": "score_inversion",
                    "base_threshold": 50,
                    "base_pf": 1.1,
                    "best_pf_threshold": 50,
                    "best_pf": 1.1,
                    "high_threshold": 70,
                    "high_pf": 0.7,
                    "pf_delta_high_vs_base": -0.4,
                    "recommendation": "refit side-specific scoring; avoid high-score gate for this side",
                }
            ],
        }
        template = "\n".join(
            [
                "; template",
                "InpEnableBuy=true||false||0||true||N",
                "InpEnableSell=true||false||0||true||N",
                "InpBuyRiskReward=4.0||2.0||1.0||5.0||Y",
            ]
        )
        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            input_json = root / "report.json"
            output_json = root / "recommendation.json"
            output_md = root / "recommendation.md"
            template_path = root / "template.set"
            output_set = root / "next.set"
            input_json.write_text(json.dumps({"ok": True, "summary": summary}), encoding="utf-8")
            template_path.write_text(template, encoding="utf-8")
            output_set.write_text("keep existing focused set\n", encoding="utf-8")

            with redirect_stdout(io.StringIO()):
                exit_code = mt5_optimization_recommend_main(
                    [
                        "--input",
                        str(input_json),
                        "--output-json",
                        str(output_json),
                        "--output-md",
                        str(output_md),
                        "--template-set",
                        str(template_path),
                        "--output-set",
                        str(output_set),
                        "--focus-side",
                        "buy",
                    ]
                )

            payload = json.loads(output_json.read_text(encoding="utf-8"))
            metadata = payload["recommendation"]["set_metadata"]
            markdown = output_md.read_text(encoding="utf-8")
            output_set_text = output_set.read_text(encoding="utf-8")

        self.assertEqual(exit_code, 2)
        self.assertTrue(metadata["diagnostic_only"])
        self.assertTrue(metadata["skipped_write"])
        self.assertEqual(metadata["skip_reason"], "diagnostic_only")
        self.assertEqual(output_set_text, "keep existing focused set\n")
        self.assertIn("## Next Set", markdown)
        self.assertIn("Skipped write: True", markdown)
        self.assertIn("Skip reason: diagnostic_only", markdown)

