    def test_mt5_manual_test_queue_can_append_static_optimization_configs(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            config = root / "Swing_Evaluation_Trader_optimization.ini"
            config.write_text(
                "\n".join(
                    [
                        "[Tester]",
                        "Expert=Swing_Evaluation_Trader.ex5",
                        "ExpertParameters=Swing_Evaluation_Trader_optimization.set",
                        "Symbol=XAUUSD-m",
                        "Period=M1",
                        "Model=4",
                        "Optimization=2",
                        "OptimizationCriterion=6",
                        "FromDate=2026.06.30",
                        "ToDate=2026.07.08",
                        "ForwardMode=3",
                        r"Report=Tester\Swing_Evaluation_Trader_optimization",
                    ]
                ),
                encoding="utf-8",
            )
            back_forward = root / "back_forward.json"
            sell = root / "sell.json"
            buy = root / "buy.json"
            for path in (back_forward, sell, buy):
                path.write_text("{}", encoding="utf-8")

            payload = build_mt5_manual_test_queue(
                back_forward_run=str(back_forward),
                sell_next_action_run=str(sell),
                buy_next_action_run=str(buy),
                mt5_root=root / "drive_c" / "Program Files" / "MetaTrader 5",
                wine_path="/wine",
                queue_json="runtime/latest_mt5_manual_test_queue_with_optimization.json",
                generated_at="2026.07.14 12:30",
                static_strategy_configs=[str(config)],
            )
            markdown = format_mt5_manual_test_queue_markdown(payload)

        self.assertTrue(payload["ok"])
        self.assertEqual(payload["entry_count"], 1)
        self.assertEqual(payload["total_entry_count"], 4)
        self.assertEqual(payload["step_count"], 1)
        self.assertEqual(payload["static_strategy_configs"], [str(config)])
        self.assertEqual(payload["static_strategy_config_count"], 1)
        self.assertEqual(payload["static_candidate_label_count"], 0)
        self.assertEqual(
            payload["static_strategy_config_state"][str(config)]["manual_run_start_after"],
            "2026.07.14 12:30",
        )
        self.assertEqual(payload["entries"][3]["id"], "static_optimization")
        self.assertEqual(payload["strategy_tester_targets"][0]["purpose"], "Optimization")
        self.assertEqual(
            payload["strategy_tester_targets"][0]["optimization_label"],
            "Fast genetic algorithm",
        )
        self.assertEqual(payload["strategy_tester_targets"][0]["run_type"], "optimization_forward")
        self.assertEqual(payload["strategy_tester_targets"][0]["expected_report_artifact"], "XML + forward XML + Agent CSV")
        self.assertEqual(
            payload["execution_checklist"][0]["optimization_label"],
            "Fast genetic algorithm",
        )
        self.assertTrue(payload["execution_checklist"][0]["pass_budget_available"])
        self.assertEqual(payload["execution_checklist"][0]["optimized_input_count"], 11)
        self.assertEqual(payload["execution_checklist"][0]["estimated_full_factorial_passes"], 165888)
        self.assertIn(
            "InpSwingDepth",
            payload["execution_checklist"][0]["pass_budget"]["optimized_input_names"],
        )
        self.assertIn("Tester\\Swing_Evaluation_Trader_optimization", payload["entries"][3]["collect_only_command_text"])
        self.assertIn("--collect-only", payload["entries"][3]["collect_only_command_text"])
