    def test_mt5_manual_auto_collect_watch_waits_without_execute_ready(self):
        dry_stdout = json.dumps(
            {
                "ok": False,
                "status": "waiting_for_ready_collect_entries",
                "next_action": "run_manual_strategy_tester_steps_and_wait_for_reports",
                "selected_count": 0,
                "waiting_count": 1,
                "invalid_count": 0,
                "queue_refresh": {"status": "refreshed", "ok": True},
            }
        )
        calls = []

        def fake_run(command, text, capture_output):
            calls.append(command)
            return subprocess.CompletedProcess(command, 2, stdout=dry_stdout, stderr="")

        with patch("analysis.mt5_manual_auto_collect_watch.subprocess.run", side_effect=fake_run):
            report = mt5_manual_auto_collect_once(
                queue="queue.json",
                collect_output_json="collect.json",
                collect_output_md="collect.md",
                execute_ready=False,
            )
        markdown = format_mt5_manual_auto_collect_markdown(report)

        self.assertTrue(report["ok"])
        self.assertFalse(report["ready_to_execute"])
        self.assertFalse(report["ready_for_collect_execute"])
        self.assertEqual(report["status"], "waiting_for_ready_collect_entries")
        self.assertEqual(report["selected_count"], 0)
        self.assertEqual(report["waiting_count"], 1)
        self.assertEqual(report["invalid_count"], 0)
        self.assertEqual(report["execution"]["status"], "not_requested")
        self.assertIn("methods/swing_eval/analysis/mt5_manual_collect.py", report["collect_dry_run_command_text"])
        self.assertNotIn("--execute", report["collect_dry_run_command_text"])
        self.assertIn("--execute", report["collect_execute_command_text"])
        self.assertIn("Collect dry-run command:", markdown)
        self.assertIn("Collect execute command:", markdown)
        self.assertEqual(len(calls), 1)
        self.assertIn("MT5 Manual Auto Collect Watch", markdown)
        self.assertIn("waiting_for_ready_collect_entries", markdown)

    def test_mt5_manual_auto_collect_watch_executes_ready_collect_when_enabled(self):
        dry_stdout = json.dumps(
            {
                "ok": True,
                "status": "ready_for_collect_execute",
                "next_action": "run_mt5_manual_collect_with_execute",
                "selected_count": 1,
                "waiting_count": 0,
                "invalid_count": 0,
                "queue_refresh": {"status": "refreshed", "ok": True},
            }
        )
        execute_stdout = json.dumps(
            {
                "ok": True,
                "status": "collect_executed",
                "next_action": "refresh_mt5_tester_status_after_collect",
                "selected_count": 1,
                "waiting_count": 0,
                "invalid_count": 0,
                "queue_refresh": {"status": "refreshed", "ok": True},
            }
        )
        calls = []

        def fake_run(command, text, capture_output):
            calls.append(command)
            if len(calls) == 1:
                return subprocess.CompletedProcess(command, 0, stdout=dry_stdout, stderr="")
            return subprocess.CompletedProcess(command, 0, stdout=execute_stdout, stderr="")

        with patch("analysis.mt5_manual_auto_collect_watch.subprocess.run", side_effect=fake_run):
            report = mt5_manual_auto_collect_once(
                queue="queue.json",
                collect_output_json="collect.json",
                collect_output_md="collect.md",
                execute_ready=True,
            )

        self.assertTrue(report["ok"])
        self.assertTrue(report["ready_to_execute"])
        self.assertTrue(report["ready_for_collect_execute"])
        self.assertEqual(report["status"], "collect_executed")
        self.assertEqual(report["selected_count"], 1)
        self.assertEqual(report["waiting_count"], 0)
        self.assertEqual(report["invalid_count"], 0)
        self.assertEqual(report["execution"]["status"], "collect_executed")
        self.assertEqual(len(calls), 2)
        self.assertNotIn("--execute", calls[0])
        self.assertIn("--execute", calls[1])
        self.assertIn("--refresh-post-collect-analysis", calls[1])
        self.assertIn("--execute", report["collect_execute_command_text"])
        self.assertIn("--refresh-post-collect-analysis", report["collect_execute_command_text"])

