    def test_mt5_manual_auto_collect_watch_one_shot_does_not_clobber_daemon_state_by_default(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            output_json = root / "watch.json"
            output_md = root / "watch.md"
            dry_stdout = json.dumps(
                {
                    "ok": False,
                    "status": "waiting_for_ready_collect_entries",
                    "next_action": "run_manual_strategy_tester_steps_and_wait_for_reports",
                    "selected_count": 0,
                    "waiting_count": 1,
                    "invalid_count": 0,
                    "queue_refresh_status": "refreshed",
                    "queue_refresh_ok": True,
                }
            )

            def fake_run(command, text, capture_output):
                return subprocess.CompletedProcess(command, 2, stdout=dry_stdout, stderr="")

            with patch("analysis.mt5_manual_auto_collect_watch.subprocess.run", side_effect=fake_run):
                with redirect_stdout(io.StringIO()):
                    exit_code = mt5_manual_auto_collect_watch_main(
                        [
                            "--queue",
                            str(root / "queue.json"),
                            "--collect-output-json",
                            str(root / "collect.json"),
                            "--collect-output-md",
                            str(root / "collect.md"),
                            "--output-json",
                            str(output_json),
                            "--output-md",
                            str(output_md),
                            "--no-refresh-queue-launch",
                            "--no-refresh-operator-packet",
                            "--max-runs",
                            "1",
                        ]
                    )

            payload = json.loads(output_json.read_text(encoding="utf-8"))
            markdown = output_md.read_text(encoding="utf-8")

        self.assertEqual(exit_code, 0)
        self.assertEqual(payload["status"], "waiting_for_ready_collect_entries")
        self.assertEqual(payload["heartbeat"], "")
