    def test_mt5_manual_test_queue_excludes_stale_side_runner_from_execution_checklist(self):
        def source_payload(
            *,
            generated_at: str,
            command: str,
            focus_side: str = "",
            current_for_execution: bool | str = "",
            gate_stale_reason: str = "",
        ) -> dict[str, object]:
            step = {
                "order": 1,
                "label": "score_weight_sample_collection" if focus_side else "backtest",
                "config": "methods/swing_eval/mt5/TesterConfigs/Swing_Evaluation_Trader_sample_collection.ini"
                if focus_side
                else "methods/swing_eval/mt5/TesterConfigs/Swing_Evaluation_Trader_backtest.ini",
                "expert": "Swing_Evaluation_Trader.ex5",
                "symbol": "XAUUSD-m",
                "period": "M1",
                "model_label": "Every tick based on real ticks",
                "from_date": "2026.06.30",
                "to_date": "2026.07.08",
                "forward_label": "1/4" if focus_side else "Disabled",
                "expert_parameters": "Swing_Evaluation_Trader_sample_collection.set"
                if focus_side
                else "Swing_Evaluation_Trader_backtest.set",
                "report_name": "Tester\\Swing_Evaluation_Trader_sample_collection_buy"
                if focus_side == "buy"
                else "Tester\\Swing_Evaluation_Trader_backtest",
            }
            return {
                "ok": True,
                "generated_at": generated_at,
                "runner_generated_at": generated_at,
                "promotion_generated_at": generated_at,
                "promotion_decision": "not_ready",
                "runner_promotion_generated_at": generated_at,
                "current_promotion_generated_at": "2026.07.14 12:40",
                "current_for_execution": current_for_execution,
                "gate_stale_reason": gate_stale_reason,
                "target": "score_weight_sample_collection" if focus_side else "",
                "focus_side": focus_side,
                "manual_strategy_tester": {
                    "available": True,
                    "manual_run_start_after": generated_at,
                    "recommended_collect_only_command_text": command,
                    "steps": [step],
                },
                "manual_collect_readiness": {
                    "ready": True,
                    "status": "ready_to_collect",
                    "reason": "all_reports_and_agent_csv_fresh",
                    "blocking_reasons": [],
                    "next_action": "run_collect_only_command",
                    "csv_count": 2,
                    "modified_after": generated_at,
                    "steps": [],
                },
            }

        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            back_forward = root / "latest_mt5_back_forward_run.json"
            sell = root / "latest_mt5_next_action_run.json"
            buy = root / "latest_mt5_next_action_run_buy.json"
            back_forward.write_text(
                json.dumps(
                    source_payload(
                        generated_at="2026.07.14 12:30",
                        command="python3 methods/swing_eval/analysis/mt5_back_forward_run.py --mode backtest --collect-only",
                    )
                ),
                encoding="utf-8",
            )
            sell.write_text(json.dumps({}), encoding="utf-8")
            buy.write_text(
                json.dumps(
                    source_payload(
                        generated_at="2026.07.14 12:31",
                        command="python3 methods/swing_eval/analysis/mt5_tester_run.py --collect-only --focus-side buy",
                        focus_side="buy",
                        current_for_execution=False,
                        gate_stale_reason="selected_action_mismatch",
                    )
                ),
                encoding="utf-8",
            )

            payload = build_mt5_manual_test_queue(
                back_forward_run=str(back_forward),
                sell_next_action_run=str(sell),
                buy_next_action_run=str(buy),
                generated_at="2026.07.14 12:41",
            )
            markdown = format_mt5_manual_test_queue_markdown(payload)

        self.assertFalse(payload["ok"])
        self.assertEqual(payload["status"], "stale_runner_artifacts")
        self.assertEqual(payload["next_action"], "refresh_stale_runner_artifacts")
        self.assertEqual(payload["stale_entry_count"], 1)
        self.assertEqual(payload["entry_count"], 1)
        stale_entry = next(entry for entry in payload["entries"] if entry["id"] == "score_weight_buy")
        self.assertFalse(stale_entry["available"])
        self.assertFalse(stale_entry["collect_ready"])
        self.assertEqual(
            stale_entry["stale_reasons"],
            ["current_for_execution_false:selected_action_mismatch"],
        )
        self.assertEqual(len(payload["execution_checklist"]), 1)
        self.assertEqual(payload["execution_checklist"][0]["queue_id"], "back_forward")
        self.assertIn("Stale Runner Refresh", markdown)
        self.assertIn("current_for_execution_false:selected_action_mismatch", markdown)
        self.assertIn("--focus-side buy", markdown)
        self.assertNotIn("| [ ] | 2 | score_weight_buy/score_weight_sample_collection |", markdown)

