    def test_mt5_manual_queue_launch_detaches_direct_config_launch(self):
        class FakePopen:
            pid = 4567

        queue = {
            "status": "waiting_for_manual_strategy_tester_results",
            "execution_checklist": [
                {
                    "order": 1,
                    "queue_id": "back_forward",
                    "step_label": "backtest",
                    "symbol": "XAUUSD-m",
                    "period": "M1",
                    "launch_command_kind": "direct_config",
                    "launch_command": ["/wine", "terminal64.exe", "/config:backtest.ini"],
                    "launch_command_text": "/wine terminal64.exe /config:backtest.ini",
                }
            ],
        }
        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            queue_path = root / "queue.json"
            queue_path.write_text(json.dumps(queue), encoding="utf-8")
            with patch(
                "analysis.mt5_manual_queue_launch.discover_running_terminal_processes",
                return_value=[],
            ), patch(
                "analysis.mt5_manual_queue_launch.subprocess.Popen",
                return_value=FakePopen(),
            ) as popen_mock, patch("analysis.mt5_manual_queue_launch.subprocess.run") as run_mock:
                payload = build_mt5_manual_queue_launch_plan(
                    queue_path=queue_path,
                    execute=True,
                    detached=True,
                )
                markdown = format_mt5_manual_queue_launch_markdown(payload)

        self.assertTrue(payload["ok"])
        self.assertTrue(payload["detached"])
        self.assertEqual(payload["status"], "launched")
        self.assertEqual(payload["process_pid"], 4567)
        self.assertEqual(payload["next_action"], "wait_for_mt5_strategy_tester_report_then_collect")
        self.assertEqual(payload["returncode"], "")
        run_mock.assert_not_called()
        popen_mock.assert_called_once()
        popen_args, popen_kwargs = popen_mock.call_args
        self.assertEqual(popen_args[0], ["/wine", "terminal64.exe", "/config:backtest.ini"])
        self.assertEqual(popen_kwargs["stdout"], subprocess.DEVNULL)
        self.assertEqual(popen_kwargs["stderr"], subprocess.DEVNULL)
        self.assertTrue(popen_kwargs["start_new_session"])
        self.assertIn("WINEPREFIX", popen_kwargs["env"])
        self.assertEqual(popen_kwargs["cwd"], None)
        self.assertIn("Detached: True", markdown)
        self.assertIn("Process PID: 4567", markdown)

    def test_mt5_status_watch_manual_queue_launch_refresh_preserves_detached(self):
        class Args:
            skip_manual_queue_launch_refresh = False

        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            queue_path = root / "queue.json"
            output_json = root / "launch.json"
            queue_path.write_text(json.dumps({"execution_checklist": []}), encoding="utf-8")
            output_json.write_text(json.dumps({"detached": True}), encoding="utf-8")

            def fake_run(command, text, capture_output):
                self.assertTrue(text)
                self.assertTrue(capture_output)
                self.assertIn("--detached", command)
                return subprocess.CompletedProcess(
                    args=command,
                    returncode=0,
                    stdout=json.dumps(
                        {
                            "ok": True,
                            "status": "planned",
                            "detached": True,
                            "queue_refresh_status": "refreshed",
                            "queue_refresh_ok": True,
                            "queue_refresh_source_count": 1,
                            "selected": True,
                            "queue_operator_handoff_next_mt5_step": {
                                "queue_id": "back_forward",
                                "step_label": "backtest",
                            },
                            "blocked": False,
                            "blocked_reasons": [],
                        }
                    ),
                    stderr="",
                )

            with patch("analysis.mt5_tester_status_watch.subprocess.run", side_effect=fake_run):
                payload = mt5_status_watch_refresh_manual_queue_launch_queue_once(
                    Args(),
                    queue_path=str(queue_path),
                    output_json=str(output_json),
                    prefix="manual_queue_launch_refresh",
                )

        self.assertTrue(payload["manual_queue_launch_refresh_detached"])
        self.assertEqual(payload["manual_queue_launch_refresh_status"], "planned")
        self.assertEqual(payload["manual_queue_launch_refresh_selected_queue_id"], "back_forward")

