        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            back_forward = root / "back_forward.json"
            sell = root / "sell.json"
            buy = root / "buy.json"
            queue_path = root / "queue.json"
            output_json = root / "collect.json"
            output_md = root / "collect.md"
            for path, command in (
                (back_forward, "python3 methods/swing_eval/analysis/mt5_back_forward_run.py --mode both --collect-only"),
                (sell, "python3 methods/swing_eval/analysis/mt5_tester_run.py --collect-only --focus-side sell"),
                (buy, "python3 methods/swing_eval/analysis/mt5_tester_run.py --collect-only --focus-side buy"),
            ):
                payload = source_payload(command)
                if path in (sell, buy):
                    payload["focus_side"] = "sell" if path == sell else "buy"
                path.write_text(json.dumps(payload, sort_keys=True), encoding="utf-8")
            source_before = {
                str(path): path.read_text(encoding="utf-8")
                for path in (back_forward, sell, buy)
            }
            queue = build_mt5_manual_test_queue(
                back_forward_run=str(back_forward),
                sell_next_action_run=str(sell),
                buy_next_action_run=str(buy),
                generated_at="2026.07.14 12:31",
            )
            queue["queue_json"] = str(queue_path)
            queue_path.write_text(json.dumps(queue), encoding="utf-8")

            with patch(
                "analysis.mt5_manual_collect.back_forward_manual_collect_readiness",
                return_value=unchanged_readiness,
            ), patch(
                "analysis.mt5_manual_collect.next_action_manual_collect_readiness",
                return_value=unchanged_readiness,
            ):
                with redirect_stdout(io.StringIO()):
                    exit_code = mt5_manual_collect_main(
                        [
                            "--queue",
                            str(queue_path),
                            "--output-json",
                            str(output_json),
                            "--output-md",
                            str(output_md),
                        ]
                    )
            payload = json.loads(output_json.read_text(encoding="utf-8"))
            source_after = {
                str(path): path.read_text(encoding="utf-8")
                for path in (back_forward, sell, buy)
            }

        self.assertEqual(exit_code, 2)
        self.assertEqual(source_after, source_before)
        self.assertEqual(payload["next_action"], "run_manual_strategy_tester_steps_and_wait_for_reports")
        self.assertEqual(payload["blocking_reasons"], ["agent_csv_missing_or_stale"])
        self.assertTrue(
            all(row["changed"] is False for row in payload["queue_refresh"]["refreshed_sources"])
        )

