    def test_mt5_compile_syncs_workspace_source_before_compile(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            workspace = root / "workspace"
            drive_c = root / "drive_c"
            mt5_root = drive_c / "Program Files" / "MetaTrader 5"
            workspace_source = workspace / "methods" / "swing_eval" / "mt5" / "Experts" / "Swing_Evaluation_Trader.mq5"
            mt5_source = mt5_root / "MQL5" / "Experts" / "Swing_Evaluation_Trader.mq5"
            mt5_binary = mt5_root / "MQL5" / "Experts" / "Swing_Evaluation_Trader.ex5"
            compile_log = mt5_root / "logs" / "compile_Swing_Evaluation_Trader.log"
            metaeditor_log = mt5_root / "logs" / "metaeditor.log"
            workspace_source.parent.mkdir(parents=True)
            mt5_source.parent.mkdir(parents=True)
            mt5_binary.parent.mkdir(parents=True, exist_ok=True)
            compile_log.parent.mkdir(parents=True, exist_ok=True)
            workspace_source.write_text("// current\n", encoding="utf-8")
            mt5_source.write_text("// stale\n", encoding="utf-8")
            mt5_binary.write_bytes(b"old")
            old_time = datetime(2026, 7, 8, 12, 0).timestamp()
            os.utime(mt5_binary, (old_time, old_time))

            def fake_compile(*_args, **_kwargs):
                mt5_binary.write_bytes(b"new")
                compile_log.write_bytes("Compile Swing_Evaluation_Trader.mq5 ok\n".encode("utf-16le"))
                metaeditor_log.write_bytes("Swing_Evaluation_Trader.mq5 compiled\n".encode("utf-16le"))
                new_time = workspace_source.stat().st_mtime + 300
                os.utime(mt5_binary, (new_time, new_time))
                return subprocess.CompletedProcess(args=[], returncode=0, stdout="", stderr="")

            with patch("analysis.mt5_compile.subprocess.run", side_effect=fake_compile):
                payload = run_compile(
                    workspace_root=workspace,
                    mt5_root=mt5_root,
                    wine_path="/Applications/MetaTrader 5.app/Contents/SharedSupport/wine/bin/wine",
                    wineprefix=root / "wineprefix",
                    item_names=["Swing_Evaluation_Trader"],
                    timeout_seconds=1,
                )

            self.assertEqual(mt5_source.read_text(encoding="utf-8"), "// current\n")
            self.assertTrue(payload["ok"])
            self.assertEqual(payload["runs"][0]["source_sync"], "copied")
            self.assertEqual(
                {row["kind"]: row["exists"] for row in payload["runs"][0]["metaeditor_log_candidates"]},
                {"compile_log": True, "metaeditor_log": True},
            )
            self.assertEqual(payload["runs"][0]["compile_log_lines"], ["Compile Swing_Evaluation_Trader.mq5 ok"])
            self.assertEqual(payload["runs"][0]["metaeditor_log_lines"], ["Swing_Evaluation_Trader.mq5 compiled"])
            markdown = format_compile_run_markdown(payload)
            self.assertIn("compile_log=yes", markdown)
            self.assertIn("metaeditor_log=yes", markdown)
            self.assertTrue(payload["status"]["all_sources_synced"])
            self.assertTrue(payload["status"]["all_compiled_fresh"])

