    def test_mt5_back_forward_ready_status_preflight_requires_matching_dry_run_status(self):
        steps = build_mt5_back_forward_plan(
            mode="both",
            execute=True,
            timeout_seconds=3600,
            since_minutes=120.0,
            min_closed=20,
            run_id_prefix="manual_check",
        )
        dry_run_steps = build_mt5_back_forward_plan(
            mode="both",
            execute=False,
            timeout_seconds=3600,
            since_minutes=120.0,
            min_closed=20,
            run_id_prefix="manual_check",
        )
        status_payload = {
            "generated_at": "2026.07.13 06:00",
            "back_forward_runner": {
                "exists": True,
                "ok": True,
                "dry_run": True,
                "mode": "both",
                "step_labels": ["backtest", "forward"],
                "steps": dry_run_steps,
                "execution_conditions": mt5_back_forward_test_execution_conditions(),
            },
            "back_forward_execution": {"ready": True, "status": "ready", "reasons": []},
        }
        with tempfile.TemporaryDirectory() as tmpdir:
            status_path = Path(tmpdir) / "latest_mt5_tester_status.json"
            status_path.write_text(json.dumps(status_payload), encoding="utf-8")

            ready = mt5_back_forward_ready_status_preflight(
                steps,
                mode="both",
                status_path=status_path,
                max_age_seconds=999999,
            )

            status_payload["back_forward_runner"]["steps"][1]["config"] = "methods/swing_eval/mt5/TesterConfigs/other.ini"
            status_path.write_text(json.dumps(status_payload), encoding="utf-8")
            mismatched = mt5_back_forward_ready_status_preflight(
                steps,
                mode="both",
                status_path=status_path,
                max_age_seconds=999999,
            )
            status_payload["back_forward_runner"]["steps"][1]["config"] = (
                "methods/swing_eval/mt5/TesterConfigs/Swing_Evaluation_Trader_forward_test.ini"
            )
            status_payload["back_forward_runner"]["steps"][0]["expert_parameters"] = (
                "Swing_Evaluation_Trader_forward_test.set"
            )
            status_path.write_text(json.dumps(status_payload), encoding="utf-8")
            set_mismatched = mt5_back_forward_ready_status_preflight(
                steps,
                mode="both",
                status_path=status_path,
                max_age_seconds=999999,
            )

        self.assertTrue(ready["ok"])
        self.assertFalse(mismatched["ok"])
        self.assertIn("ready_status_plan_mismatch", mismatched["reasons"])
        self.assertIn("config:forward:methods/swing_eval/mt5/TesterConfigs/other.ini->methods/swing_eval/mt5/TesterConfigs/Swing_Evaluation_Trader_forward_test.ini", mismatched["mismatches"])
        self.assertFalse(set_mismatched["ok"])
        self.assertIn("ready_status_plan_mismatch", set_mismatched["reasons"])
        self.assertIn(
            "expert_parameters:backtest:Swing_Evaluation_Trader_forward_test.set->Swing_Evaluation_Trader_backtest.set",
            set_mismatched["mismatches"],
        )
        self.assertIn("expert_parameters", set_mismatched["checked_step_keys"])

