    def test_mt5_back_forward_dry_run_records_execution_conditions(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            output_json = root / "latest_mt5_back_forward_run.json"
            output_md = root / "latest_mt5_back_forward_run.md"
            with redirect_stdout(io.StringIO()):
                returncode = mt5_back_forward_run_main(
                    [
                        "--mode",
                        "both",
                        "--timeout-seconds",
                        "10800",
                        "--since-minutes",
                        "360.0",
                        "--min-closed",
                        "100",
                        "--from-date",
                        "2025.01.01",
                        "--to-date",
                        "2025.12.31",
                        "--sync-expert-parameters-set",
                        "--skip-archive-preview",
                        "--output-json",
                        str(output_json),
                        "--output-md",
                        str(output_md),
                    ]
                )
            payload = json.loads(output_json.read_text(encoding="utf-8"))
            markdown = output_md.read_text(encoding="utf-8")

        conditions = payload["execution_conditions"]
