        self.assertEqual(conditions["per_step_timeout_seconds"], 10800)
        self.assertEqual(conditions["since_minutes"], 360.0)
        self.assertEqual(conditions["min_closed"], 100)
        self.assertEqual(conditions["from_date"], "2025.01.01")
        self.assertEqual(conditions["to_date"], "2025.12.31")
