        hints = payload["execution_hints"]
        self.assertIn("--execute", hints["execute_command"])
        self.assertIn("--refresh-ready-status", hints["execute_command"])
        self.assertIn("--run-id-prefix", hints["execute_command"])
        self.assertIn(payload["run_id_prefix"], hints["execute_command"])
        self.assertIn("--timeout-seconds", hints["execute_command"])
        self.assertIn("10800", hints["execute_command"])
