    def test_mt5_back_forward_dry_run_can_run_archive_preview_only(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            output_json = root / "latest_mt5_back_forward_run.json"
            output_md = root / "latest_mt5_back_forward_run.md"

            def fake_run(command, *_args, **_kwargs):
                command = [str(item) for item in command]
                output_path = Path(command[command.index("--output-json") + 1])
                output_md_path = Path(command[command.index("--output-md") + 1])
                run_id = command[command.index("--run-id") + 1]
                output_path.write_text(
                    json.dumps(
                        {
                            "generated_at": "2026.07.13 06:00",
                            "ok": True,
                            "execute": False,
                            "count": 0,
                            "run_id": run_id,
                            "include_source_time": True,
                            "source_time_coverage": {
                                "close_rows": 0,
                                "close_rows_with_server_time": 0,
                                "first_server_time": "",
                                "last_server_time": "",
                            },
                        }
                    ),
                    encoding="utf-8",
                )
                output_md_path.write_text("# archive preview\n", encoding="utf-8")
                return subprocess.CompletedProcess(command, 0, stdout="archive ok", stderr="")

            with patch("analysis.mt5_back_forward_run.subprocess.run", side_effect=fake_run) as run:
                with redirect_stdout(io.StringIO()):
                    returncode = mt5_back_forward_run_main(
                        [
                            "--mode",
                            "both",
                            "--run-archive-preview",
                            "--run-id-prefix",
                            "manual_check",
                            "--timeout-seconds",
                            "3600",
                            "--since-minutes",
                            "120.0",
                            "--min-closed",
                            "20",
                            "--output-json",
                            str(output_json),
                            "--output-md",
                            str(output_md),
                        ]
                    )

            payload = json.loads(output_json.read_text(encoding="utf-8"))
            markdown = output_md.read_text(encoding="utf-8")

        self.assertEqual(returncode, 0)
        self.assertEqual(run.call_count, 2)
        for call in run.call_args_list:
            self.assertIn("methods/swing_eval/analysis/mt5_agent_csv_archive.py", call.args[0])
            self.assertNotIn("methods/swing_eval/analysis/mt5_tester_run.py", call.args[0])
        self.assertTrue(payload["dry_run"])
        self.assertFalse(payload["execute"])
        self.assertTrue(payload["run_archive_preview"])
        self.assertEqual(payload["evidence_state"], "plan_only")
        self.assertTrue(payload["steps"][0]["archive_preview_execution"]["ok"])
        self.assertTrue(payload["steps"][0]["archive_preview_validation"]["ok"])
        self.assertTrue(payload["steps"][1]["archive_preview_validation"]["ok"])
        self.assertEqual(payload["steps"][0]["execution"]["dry_run"], True)
        self.assertEqual(payload["performance_comparison"]["thresholds"]["min_closed"], 20)
        self.assertIn("Run archive preview: True", markdown)
        self.assertIn("Archive preview result: ok=True returncode=0", markdown)
        self.assertIn("Archive preview validation: required=True ok=True reasons=", markdown)
        self.assertIn("Min closed threshold: 20", markdown)

