    def test_mt5_back_forward_execute_blocks_when_archive_preview_fails(self):
        dry_run_steps = build_mt5_back_forward_plan(
            mode="both",
            execute=False,
            timeout_seconds=3600,
            since_minutes=120.0,
            min_closed=20,
            run_id_prefix="manual_check",
        )
        status_payload = {
            "generated_at": "2026.07.13 06:00",
            "back_forward_runner": {
                "exists": True,
                "ok": True,
                "dry_run": True,
                "mode": "both",
                "step_labels": ["backtest", "forward"],
                "steps": dry_run_steps,
                "execution_conditions": mt5_back_forward_test_execution_conditions(),
            },
            "back_forward_execution": {"ready": True, "status": "ready", "reasons": []},
        }
        failed = type("Completed", (), {"returncode": 1, "stdout": "", "stderr": "archive failed"})()
        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            status_path = root / "latest_mt5_tester_status.json"
            output_json = root / "latest_mt5_back_forward_run.json"
            output_md = root / "latest_mt5_back_forward_run.md"
            status_path.write_text(json.dumps(status_payload), encoding="utf-8")

            with patch("analysis.mt5_back_forward_run.subprocess.run", return_value=failed) as run:
                with redirect_stdout(io.StringIO()):
                    returncode = mt5_back_forward_run_main(
                        [
                            "--mode",
                            "both",
                            "--execute",
                            "--run-id-prefix",
                            "manual_check",
                            "--timeout-seconds",
                            "3600",
                            "--since-minutes",
                            "120.0",
                            "--min-closed",
                            "20",
                            "--ready-status",
                            str(status_path),
                            "--output-json",
                            str(output_json),
                            "--output-md",
                            str(output_md),
                        ]
                    )

            payload = json.loads(output_json.read_text(encoding="utf-8"))
            markdown = output_md.read_text(encoding="utf-8")

        self.assertEqual(returncode, 1)
        self.assertEqual(run.call_count, 2)
        for call in run.call_args_list:
            self.assertIn("methods/swing_eval/analysis/mt5_agent_csv_archive.py", call.args[0])
            self.assertNotIn("methods/swing_eval/analysis/mt5_tester_run.py", call.args[0])
        self.assertFalse(payload["ok"])
        self.assertEqual(payload["blocked_before_steps"], "archive_preview_not_ok")
        self.assertEqual(payload["evidence_state"], "executed_blocked")
        self.assertEqual(payload["steps"][0]["archive_preview_execution"]["returncode"], 1)
        self.assertFalse(payload["steps"][0]["archive_preview_validation"]["ok"])
        self.assertIn("archive_preview_command_failed", payload["steps"][0]["archive_preview_validation"]["reasons"])
        self.assertEqual(payload["steps"][0]["execution"]["skip_reason"], "archive_preview_not_ok")
        self.assertIn("Blocked before steps: archive_preview_not_ok", markdown)
        self.assertIn("Archive preview result: ok=False returncode=1", markdown)

