    def test_mt5_tester_run_terminal_records_timeout_deadline(self):
        completed = type("Completed", (), {"returncode": 0, "stdout": "ok", "stderr": ""})()
        with tempfile.TemporaryDirectory() as tmpdir, patch(
            "analysis.mt5_tester_run.time.time",
            side_effect=[1_800_000_000.0, 1_800_000_030.0],
        ), patch("analysis.mt5_tester_run.subprocess.run", return_value=completed) as run:
            result = run_terminal(
                command=["/wine", "terminal64.exe", "/config:run.ini"],
                mt5_root=tmpdir,
                wineprefix=Path(tmpdir) / "wineprefix",
                timeout_seconds=120,
            )

        self.assertEqual(result["timeout_seconds"], 120)
        self.assertEqual(result["timeout_minutes"], 2.0)
        self.assertEqual(result["elapsed_seconds"], 30.0)
        self.assertFalse(result["timeout"])
        self.assertTrue(result["started_at"])
        self.assertTrue(result["finished_at"])
        self.assertTrue(result["deadline_at"])
        self.assertEqual(run.call_args.kwargs["timeout"], 120)

