        markdown = format_tester_run_markdown(payload)
        self.assertIn("## Running Terminal Detection", markdown)
        self.assertIn("Blocked by running terminal: True", markdown)
        self.assertIn("| 123 | C:\\Program Files\\MetaTrader 5\\terminal64.exe |", markdown)

