        self.assertIn("Score weight regime shortage: 20/20, folds 0/1", markdown)
        self.assertIn("Score weight set walk-forward: walk_forward_candidate_failed", markdown)
        self.assertIn("Score weight set skip reason: walk_forward_not_passed", markdown)
        self.assertIn("| 1 | mt5_optimization | reject_chronologically_unstable_optimization |", markdown)
        self.assertIn("--target mt5_optimization --execute --allow-non-tester-primary", markdown)
        self.assertIn("python3 methods/swing_eval/analysis/mt5_optimization_recommend.py", markdown)

