    def test_mt5_tester_status_reestimates_pass_budget_from_current_set(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            tester_run = root / "latest_mt5_tester_run.json"
            promotion_gate = root / "latest_promotion_gate.json"
            compile_status_path = root / "latest_mt5_compile_status.json"
            optimization_report = root / "latest_mt5_optimization_report.json"
            set_file = root / "current.set"
            set_file.write_text(
                "\n".join(
                    [
                        "InpA=1||1||1||3||Y",
                        "InpB=true||false||0||true||Y",
                        "InpC=0.2||0.2||0.2||0.6||Y",
                    ]
                ),
                encoding="utf-8",
            )
            tester_run.write_text(json.dumps({"generated_at": "2026.07.09 10:17", "ok": False}), encoding="utf-8")
            promotion_gate.write_text(json.dumps({"decision": "not_ready", "checks": []}), encoding="utf-8")
            compile_status_path.write_text(
                json.dumps({"summary": {"all_sources_synced": True, "all_compiled_fresh": True}}), encoding="utf-8"
            )
            optimization_report.write_text(
                json.dumps(
                    {
                        "summary": {
                            "generated_at": "2026.07.09 10:19",
                            "optimization_pass_budget": {
                                "available": True,
                                "set_file": str(set_file),
                                "optimized_input_count": 1,
                                "estimated_full_factorial_passes": 2,
                                "executed_tester_xml_rows": {"back": 9, "forward": 6},
                            },
                        }
                    }
                ),
                encoding="utf-8",
            )

            with patch("analysis.mt5_tester_status.discover_running_terminal_processes", return_value=[]):
                status = mt5_tester_status(
                    tester_run_path=tester_run,
                    promotion_gate_path=promotion_gate,
                    compile_status_path=compile_status_path,
                    optimization_report_path=optimization_report,
                )

        self.assertTrue(status["pass_budget"]["set_file_exists"])
        self.assertTrue(status["pass_budget"]["set_file_reestimated"])
        self.assertEqual(status["pass_budget"]["optimized_input_count"], 3)
        self.assertEqual(status["pass_budget"]["estimated_full_factorial_passes"], 18)
        self.assertEqual(status["pass_budget"]["executed_tester_xml_rows"], {"back": 9, "forward": 6})
        self.assertEqual(status["pass_budget"]["ratio_vs_full_factorial"], {"back": 0.5, "forward": 0.3333})
        self.assertEqual(status["pass_budget"]["max_executed_tester_xml_rows"], 9)
        self.assertEqual(status["pass_budget"]["full_factorial_progress_ratio"], 0.5)
