    def test_mt5_tester_status_marks_old_terminal_blocker_ready_after_terminal_closed(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            tester_run = root / "latest_mt5_tester_run.json"
            promotion_gate = root / "latest_promotion_gate.json"
            compile_status_path = root / "latest_mt5_compile_status.json"
            optimization_report = root / "latest_mt5_optimization_report.json"
            tester_run.write_text(
                json.dumps(
                    {
                        "generated_at": "2026.07.09 10:17",
                        "ok": False,
                        "blocked": True,
                        "blocked_components": {"terminal_already_running": True},
                        "terminal_failed": False,
                        "report_fallback_blocked": False,
                        "source_time_blocked": False,
                        "risk_preset": {"ok": True},
                        "compile_status": {"all_compiled_fresh": True},
                    }
                ),
                encoding="utf-8",
            )
            promotion_gate.write_text(json.dumps({"decision": "not_ready", "checks": []}), encoding="utf-8")
            compile_status_path.write_text(
                json.dumps({"summary": {"all_sources_synced": True, "all_compiled_fresh": True}}),
                encoding="utf-8",
            )
            optimization_report.write_text(json.dumps({"summary": {}}), encoding="utf-8")

            with patch("analysis.mt5_tester_status.discover_running_terminal_processes", return_value=[]):
                status = mt5_tester_status(
                    tester_run_path=tester_run,
                    promotion_gate_path=promotion_gate,
                    compile_status_path=compile_status_path,
                    optimization_report_path=optimization_report,
                    max_artifact_age_seconds=999999,
                )

        self.assertTrue(status["ok"])
        self.assertTrue(status["ready_for_tester_launch"])
        self.assertEqual(status["operational_status"], "ready_to_rerun_after_terminal_closed")
        self.assertIn("previous run was blocked", status["next_action"])
        markdown = format_mt5_tester_status_markdown(status)
        self.assertIn("Operational status: ready_to_rerun_after_terminal_closed", markdown)
        self.assertIn("Running: False", markdown)

    def test_mt5_tester_status_blocks_target_tester_set_not_synced(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            tester_run = root / "latest_mt5_tester_run.json"
            promotion_gate = root / "latest_promotion_gate.json"
            compile_status_path = root / "latest_mt5_compile_status.json"
            optimization_report = root / "latest_mt5_optimization_report.json"
            tester_run.write_text(
                json.dumps(
                    {
                        "generated_at": "2026.07.09 10:17",
                        "ok": False,
                        "blocked": True,
                        "blocked_components": {"tester_set_not_synced": True},
                        "tester_set_sync_blocked": True,
                        "target_tester_set_sync": {
                            "name": "Demo.set",
                            "synced": False,
                            "status": "set_not_synced",
                        },
                        "terminal_failed": False,
                        "report_fallback_blocked": False,
                        "source_time_blocked": False,
                        "risk_preset": {"ok": True},
                        "compile_status": {
                            "all_compiled_fresh": True,
                            "all_tester_sets_synced": False,
                        },
                    }
                ),
                encoding="utf-8",
            )
            promotion_gate.write_text(json.dumps({"decision": "not_ready", "checks": []}), encoding="utf-8")
            compile_status_path.write_text(
                json.dumps({"summary": {"all_sources_synced": True, "all_compiled_fresh": True}}),
                encoding="utf-8",
            )
            optimization_report.write_text(json.dumps({"summary": {}}), encoding="utf-8")

            with patch("analysis.mt5_tester_status.discover_running_terminal_processes", return_value=[]):
                status = mt5_tester_status(
                    tester_run_path=tester_run,
                    promotion_gate_path=promotion_gate,
                    compile_status_path=compile_status_path,
                    optimization_report_path=optimization_report,
                    max_artifact_age_seconds=999999,
                )

        self.assertFalse(status["ok"])
