    def test_mt5_tester_status_watch_can_refresh_without_overwriting_daemon_pid(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            output_json = root / "latest_mt5_tester_status.json"
            output_md = root / "latest_mt5_tester_status.md"
            heartbeat_path = root / "mt5_tester_status_watch_heartbeat.json"
            pid_file = root / "mt5_tester_status_watch.pid"
            pid_file.write_text("daemon-pid\n", encoding="utf-8")

            def fake_run(command, text, capture_output):
                self.assertTrue(text)
                self.assertTrue(capture_output)
                output_index = command.index("--output-json") + 1
                Path(command[output_index]).write_text(
                    json.dumps({"ok": True, "operational_status": "latest_run_ok"}),
                    encoding="utf-8",
                )
                return subprocess.CompletedProcess(
                    args=command,
                    returncode=0,
                    stdout='{"ok": true, "operational_status": "latest_run_ok"}',
                    stderr="",
                )

            with patch("analysis.mt5_tester_status_watch.subprocess.run", side_effect=fake_run):
                exit_code = mt5_tester_status_watch_main(
                    [
                        "--output-json",
                        str(output_json),
                        "--output-md",
                        str(output_md),
                        "--heartbeat",
                        str(heartbeat_path),
                        "--pid-file",
                        str(pid_file),
                        "--interval-seconds",
                        "5",
                        "--max-runs",
                        "1",
                        "--skip-pid-file-write",
                        "--skip-manual-collect-refresh",
                        "--skip-manual-queue-launch-refresh",
                    ]
                )

            heartbeat = json.loads(heartbeat_path.read_text(encoding="utf-8"))
            pid_contents = pid_file.read_text(encoding="utf-8")

        self.assertEqual(exit_code, 0)
        self.assertEqual(pid_contents, "daemon-pid\n")
        self.assertEqual(heartbeat["pid_file"], str(pid_file))
        self.assertFalse(heartbeat["pid_file_written"])
        self.assertEqual(heartbeat["watcher_pid"], os.getpid())
        self.assertEqual(heartbeat["max_runs"], 1)
        self.assertFalse(heartbeat["continuous"])
        self.assertTrue(heartbeat["ok"])
        self.assertTrue(heartbeat["status_ok"])

    def test_mt5_tester_status_watch_one_shot_does_not_clobber_daemon_state_by_default(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            output_json = root / "latest_mt5_tester_status.json"
            output_md = root / "latest_mt5_tester_status.md"
            shared_heartbeat = root / "mt5_tester_status_watch_heartbeat.json"
            shared_pid = root / "mt5_tester_status_watch.pid"
            shared_heartbeat.write_text('{"continuous": true}\n', encoding="utf-8")
            shared_pid.write_text("daemon-pid\n", encoding="utf-8")

            def fake_run(command, text, capture_output):
                self.assertTrue(text)
                self.assertTrue(capture_output)
                output_index = command.index("--output-json") + 1
                Path(command[output_index]).write_text(
                    json.dumps({"ok": True, "operational_status": "latest_run_ok"}),
                    encoding="utf-8",
                )
                return subprocess.CompletedProcess(
                    args=command,
                    returncode=0,
                    stdout='{"ok": true, "operational_status": "latest_run_ok"}',
                    stderr="",
                )

            with patch("analysis.mt5_tester_status_watch.DEFAULT_HEARTBEAT", str(shared_heartbeat)), patch(
                "analysis.mt5_tester_status_watch.DEFAULT_PID_FILE",
                str(shared_pid),
            ), patch("analysis.mt5_tester_status_watch.subprocess.run", side_effect=fake_run):
                exit_code = mt5_tester_status_watch_main(
                    [
                        "--output-json",
                        str(output_json),
                        "--output-md",
                        str(output_md),
                        "--interval-seconds",
                        "5",
                        "--max-runs",
                        "1",
                        "--skip-manual-collect-refresh",
                        "--skip-manual-queue-launch-refresh",
                    ]
                )

