    def test_mt5_tester_xml_resolution_falls_back_to_latest_pair(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            mt5_root = root / "drive_c" / "Program Files" / "MetaTrader 5"
            tester = mt5_root / "Tester"
            runtime_xml = root / "workspace" / "runtime" / "mt5_optimization"
            tester.mkdir(parents=True)
            runtime_xml.mkdir(parents=True)
            old_back = tester / "Swing_Evaluation_Trader_old.xml"
            old_forward = tester / "Swing_Evaluation_Trader_old.forward.xml"
            new_back = runtime_xml / "Swing_Evaluation_Trader_optimization.xml"
            new_forward = runtime_xml / "Swing_Evaluation_Trader_optimization.forward.xml"
            for path in (old_back, old_forward, new_back, new_forward):
                path.write_text("<Workbook />", encoding="utf-8")
            os.utime(old_back, (1_700_000_000, 1_700_000_000))
            os.utime(old_forward, (1_700_000_000, 1_700_000_000))
            os.utime(new_back, (1_700_000_500, 1_700_000_500))
            os.utime(new_forward, (1_700_000_500, 1_700_000_500))

            pairs = matching_xml_pairs([tester, runtime_xml])
            back, forward, metadata = resolve_tester_xml_paths(
                mt5_root=mt5_root,
                report_name="Tester\\Swing_Evaluation_Trader_next_optimization",
                workspace_root=root / "workspace",
            )

        self.assertEqual(pairs[0], (new_back, new_forward))
        self.assertEqual(back.resolve(), new_back.resolve())
        self.assertEqual(forward.resolve(), new_forward.resolve())
        self.assertEqual(metadata["source"], "latest_pair_fallback")
        self.assertTrue(metadata["requested_forward_xml"].endswith("Swing_Evaluation_Trader_next_optimization.forward.xml"))

