    def test_mt5_tester_run_passes_allow_diagnostic_output_set(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            workspace = root / "workspace"
            mt5_root = root / "drive_c" / "Program Files" / "MetaTrader 5"
            wineprefix = root / "wineprefix"
            config = workspace / "methods" / "swing_eval" / "mt5" / "TesterConfigs" / "run.ini"
            config.parent.mkdir(parents=True)
            mt5_root.mkdir(parents=True)
            wineprefix.mkdir(parents=True)
            config.write_text(
                "\n".join(
                    [
                        "[Tester]",
                        "Expert=Swing_Evaluation_Trader.ex5",
                        "ExpertParameters=missing.set",
                        "Optimization=2",
                        "Report=Tester\\OldReport",
                    ]
                ),
                encoding="utf-8",
            )

            with patch("analysis.mt5_tester_run.compile_status", return_value={"all_compiled_fresh": True}), patch(
                "analysis.mt5_tester_run.resolve_tester_xml_paths",
                return_value=(mt5_root / "Tester" / "back.xml", mt5_root / "Tester" / "forward.xml", {"source": "requested"}),
            ), patch(
                "analysis.mt5_tester_run.collect_outputs",
                return_value=({"overall": {"closed": 100, "pf": 1.0}}, []),
            ), patch(
                "analysis.mt5_tester_run.recommend_from_summary",
                return_value={"decision": {"adoptable": False}},
            ), patch("analysis.mt5_tester_run.write_next_set") as write_next_set_mock:
                write_next_set_mock.return_value = {
                    "path": "runtime/diagnostic.set",
                    "diagnostic_only": True,
                    "skipped_write": False,
                }
                payload = run_tester_pipeline(
                    config_path=config,
                    workspace_root=workspace,
                    mt5_root=mt5_root,
                    wine_path="/wine",
                    wineprefix=wineprefix,
                    collect_only=True,
                    output_set="runtime/diagnostic.set",
                    allow_diagnostic_output_set=True,
                )

        self.assertTrue(payload["ok"])
        self.assertTrue(payload["next_set"]["diagnostic_only"])
        self.assertTrue(payload["recommendation"]["set_metadata"]["diagnostic_only"])
        self.assertFalse(payload["recommendation"]["set_metadata"]["skipped_write"])
        self.assertEqual(write_next_set_mock.call_args.kwargs["allow_diagnostic"], True)

