    def test_mt5_tester_run_child_reports_mark_blocked_runner_failure(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            payload = {
                "ok": False,
                "generated_at": "2026.07.09 03:30",
                "blocked": False,
                "terminal_failed": True,
                "report_fallback_blocked": False,
                "source_time_blocked": False,
                "collect_only": False,
                "dry_run": False,
                "warnings": ["terminal run failed with returncode 1"],
                "report_paths": {
                    "source": "terminal_failed_not_collected",
                    "requested_back_xml": "/mt5/Tester/Expected.xml",
                    "requested_forward_xml": "/mt5/Tester/Expected.forward.xml",
                    "used_back_xml": "/mt5/Tester/Expected.xml",
                    "used_forward_xml": "/mt5/Tester/Expected.forward.xml",
                },
                "terminal_run": {
                    "started_at": "2026.07.09 03:30",
                    "deadline_at": "2026.07.09 03:45",
                    "timeout_seconds": 900,
                    "elapsed_seconds": 42.5,
                    "returncode": 1,
                    "timeout": False,
                },
                "optimization_summary": None,
                "recommendation": None,
            }
            optimization_json = root / "optimization.json"
            optimization_md = root / "optimization.md"
            recommendation_json = root / "recommendation.json"
            recommendation_md = root / "recommendation.md"

            write_child_reports(
                payload,
                optimization_json=optimization_json,
                optimization_md=optimization_md,
                recommendation_json=recommendation_json,
                recommendation_md=recommendation_md,
            )

            optimization_payload = json.loads(optimization_json.read_text(encoding="utf-8"))
            recommendation_payload = json.loads(recommendation_json.read_text(encoding="utf-8"))
            optimization_markdown = optimization_md.read_text(encoding="utf-8")
            recommendation_markdown = recommendation_md.read_text(encoding="utf-8")

        self.assertFalse(optimization_payload["ok"])
        self.assertTrue(optimization_payload["summary"]["blocked"])
        self.assertEqual(optimization_payload["summary"]["reason"], "terminal_failed")
        self.assertEqual(optimization_payload["summary"]["report_paths"]["source"], "terminal_failed_not_collected")
        self.assertFalse(recommendation_payload["ok"])
        recommendation = recommendation_payload["recommendation"]
        self.assertFalse(recommendation["decision"]["adoptable"])
        self.assertEqual(recommendation["set_metadata"]["skip_reason"], "terminal_failed")
        self.assertIn("MT5 Tester Optimization Report Not Updated", optimization_markdown)
        self.assertIn("Reason: terminal_failed", optimization_markdown)
        self.assertIn("Terminal started at: 2026.07.09 03:30", optimization_markdown)
        self.assertIn("Terminal deadline at: 2026.07.09 03:45", optimization_markdown)
        self.assertIn("Terminal elapsed seconds: 42.5", optimization_markdown)
        self.assertIn("MT5 Optimization Recommendation Not Generated", recommendation_markdown)
        self.assertIn("Terminal deadline at: 2026.07.09 03:45", recommendation_markdown)
        self.assertIn("Terminal returncode: 1", recommendation_markdown)

