            mt5_source.write_text("input int InpValue = 1;\n", encoding="utf-8")
            binary.write_text("compiled", encoding="utf-8")
            old_time = 1_700_000_000
            new_time = old_time + 120
            os.utime(binary, (old_time, old_time))
