    def test_promotion_checks_reject_stale_mt5_compile_status(self):
        compile_summary = {
            "all_sources_synced": True,
            "all_compiled_fresh": False,
            "items": [
                {
                    "kind": "expert",
                    "name": "Swing_Evaluation_Trader",
                    "status": "stale_binary",
                    "source_synced": True,
                    "compiled_fresh": False,
                    "stale_seconds": 3600,
                    "mt5_source": {"mtime": "2026.07.08 12:04"},
                    "mt5_binary": {"mtime": "2026.07.08 10:45"},
                }
            ],
        }

        checks = promotion_checks(
            history_hours=168,
            summary=promotion_summary_fixture(),
            audit={"outcome": "skipped"},
            forward_summary={},
            mt5_compile_summary=compile_summary,
            min_history_hours=168,
            min_candidates=100,
            min_avg_r=0.0,
            min_pf=1.2,
            max_losing_streak_allowed=8,
            min_side_count=30,
            min_side_pf=1.0,
            require_dry_run_passed=False,
            max_dry_run_age_seconds=3600,
            require_forward=False,
            min_forward_closed=30,
            min_forward_avg_r=0.0,
            min_forward_pf=1.2,
            require_mt5_compile=True,
        )

        self.assertTrue(next(item for item in checks if item["name"] == "mt5_compile_sources_synced")["passed"])
